import { ScrollView, StyleSheet, Text } from 'react-native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { LockedActionBanner } from '@/components/permissions';
import { ScreenShell } from '@/components/layout';
import {
  ErrorState,
  LoadingState,
  PremiumButton,
  PremiumInput,
  SuccessState,
} from '@/components/ui';
import { useEmployeeEdit } from '@/hooks/useEmployeeEdit';
import { usePermissions } from '@/hooks/usePermissions';
import { colors, spacing, typography } from '@/theme';

export function EmployeeEditScreen() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const router = useRouter();
  const { can, check, roleLabel } = usePermissions();
  const {
    employee,
    form,
    setForm,
    loading,
    error,
    save,
    saveLoading,
    saveError,
    successMessage,
    notFound,
  } = useEmployeeEdit(id);

  if (!can('office.employees.edit')) {
    return (
      <ScreenShell title="Bearbeiten" subtitle={roleLabel ?? 'Office'}>
        <LockedActionBanner
          message={check('office.employees.edit').reason ?? 'Keine Berechtigung.'}
          roleLabel={roleLabel}
        />
      </ScreenShell>
    );
  }

  if (loading && !employee) {
    return (
      <ScreenShell title="Bearbeiten" subtitle="Wird geladen…">
        <LoadingState message="Daten werden geladen…" />
      </ScreenShell>
    );
  }

  if (notFound || (error && !employee)) {
    return (
      <ScreenShell title="Bearbeiten" subtitle="Fehler">
        <ErrorState title="Fehler" message={error ?? 'Nicht gefunden.'} />
        <PremiumButton title="Zurück" variant="secondary" onPress={() => router.back()} />
      </ScreenShell>
    );
  }

  if (!employee) return null;

  return (
    <ScreenShell
      title={`${employee.firstName} ${employee.lastName}`}
      subtitle="Stammdaten bearbeiten"
      rightSlot={
        <PremiumButton title="Zurück" size="sm" variant="ghost" onPress={() => router.back()} />
      }
    >
      <ScrollView contentContainerStyle={styles.scroll}>
        {successMessage ? <SuccessState message={successMessage} /> : null}
        <PremiumInput
          label="Funktion"
          value={form.jobTitle}
          onChangeText={(v) => setForm((f) => ({ ...f, jobTitle: v }))}
        />
        <PremiumInput
          label="Telefon"
          value={form.phone}
          onChangeText={(v) => setForm((f) => ({ ...f, phone: v }))}
        />
        <PremiumInput
          label="Abteilung"
          value={form.department}
          onChangeText={(v) => setForm((f) => ({ ...f, department: v }))}
        />
        <PremiumInput
          label="Notizen"
          value={form.notes}
          onChangeText={(v) => setForm((f) => ({ ...f, notes: v }))}
        />
        {saveError ? <Text style={styles.error}>{saveError}</Text> : null}
        <PremiumButton title="Speichern" onPress={save} loading={saveLoading} />
      </ScrollView>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  scroll: { gap: spacing.md, paddingBottom: spacing.xxl },
  error: { ...typography.caption, color: colors.danger },
});
