import { StyleSheet } from 'react-native';
import { useRouter } from 'expo-router';
import { LockedActionBanner } from '@/components/permissions';
import { ScreenShell } from '@/components/layout';
import { ErrorState, PremiumButton, PremiumCard, PremiumInput, SuccessState } from '@/components/ui';
import { useEmployeeWizard } from '@/hooks/useEmployeeWizard';
import { usePermissions } from '@/hooks/usePermissions';
import { spacing } from '@/theme';

export function EmployeeCreateScreen() {
  const router = useRouter();
  const { can, check, roleLabel } = usePermissions();
  const { form, errors, submitting, submitError, createdId, updateField, submit, cancel, isSuccess } =
    useEmployeeWizard();

  if (!can('office.employees.create')) {
    return (
      <ScreenShell title="Mitarbeitende anlegen" subtitle={roleLabel ?? 'Office'}>
        <LockedActionBanner
          message={check('office.employees.create').reason ?? 'Keine Berechtigung.'}
          roleLabel={roleLabel}
        />
      </ScreenShell>
    );
  }

  if (isSuccess && createdId) {
    return (
      <ScreenShell title="Angelegt" subtitle="WP 186">
        <SuccessState message="Mitarbeitende:r wurde im Demo-Mandanten angelegt." />
        <PremiumButton
          title="Zum Profil"
          fullWidth
          onPress={() => router.replace(`/office/employees/${createdId}` as never)}
        />
      </ScreenShell>
    );
  }

  return (
    <ScreenShell title="Mitarbeitende anlegen" subtitle="WP 186">
      <PremiumCard style={styles.card}>
        <PremiumInput
          label="Vorname"
          value={form.firstName}
          onChangeText={(v) => updateField('firstName', v)}
          error={errors.firstName}
        />
        <PremiumInput
          label="Nachname"
          value={form.lastName}
          onChangeText={(v) => updateField('lastName', v)}
          error={errors.lastName}
        />
        <PremiumInput
          label="E-Mail"
          value={form.email}
          onChangeText={(v) => updateField('email', v)}
          error={errors.email}
        />
        <PremiumInput label="Telefon" value={form.phone} onChangeText={(v) => updateField('phone', v)} />
        <PremiumInput
          label="Rolle / Titel"
          value={form.jobTitle}
          onChangeText={(v) => updateField('jobTitle', v)}
          error={errors.jobTitle}
        />
        <PremiumInput
          label="Abteilung"
          value={form.department}
          onChangeText={(v) => updateField('department', v)}
        />
        {submitError ? <ErrorState title="Speichern" message={submitError} /> : null}
        <PremiumButton title="Anlegen" fullWidth loading={submitting} onPress={submit} />
        <PremiumButton
          title="Abbrechen"
          variant="secondary"
          fullWidth
          onPress={() => {
            cancel();
            router.back();
          }}
        />
      </PremiumCard>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  card: { gap: spacing.sm },
});
