import { StyleSheet, Text, View } from 'react-native';
import { useRouter } from 'expo-router';
import { CourseListCard } from '@/components/akademie';
import { ScreenShell } from '@/components/layout';
import {
  EmptyState,
  ErrorState,
  LoadingState,
  ModuleTile,
  PremiumCard,
  SectionPanel,
  SuccessState,
} from '@/components/ui';
import { useAkademieDashboard } from '@/hooks/useAkademieDashboard';
import { usePermissions } from '@/hooks/usePermissions';
import { wp438A11y } from '@/lib/a11y/wp438-akademie';
import { colors, spacing, typography } from '@/theme';

function StatTile({ label, value, accent }: { label: string; value: number; accent: string }) {
  return (
    <PremiumCard style={styles.statTile} accentColor={accent}>
      <Text style={styles.statValue}>{value}</Text>
      <Text style={styles.statLabel}>{label}</Text>
    </PremiumCard>
  );
}

export function AkademieIndexScreen() {
  const router = useRouter();
  const { can, roleLabel } = usePermissions();
  const { stats, upcomingCourses, loading, error, showSuccess, refresh } = useAkademieDashboard();

  if (loading && !stats) {
    return (
      <ScreenShell title="CareSuite+ Akademie" subtitle="Schulungen & Zertifikate">
        <LoadingState message="Dashboard wird geladen…" />
      </ScreenShell>
    );
  }

  if (error && !stats) {
    return (
      <ScreenShell title="CareSuite+ Akademie" subtitle="Fehler">
        <ErrorState message={error} onRetry={refresh} />
      </ScreenShell>
    );
  }

  return (
    <ScreenShell
      title="CareSuite+ Akademie"
      subtitle={`Schulungen & Zertifikate · ${roleLabel ?? 'Demo'}`}
      a11yMeta={wp438A11y}
    >
      {showSuccess ? <SuccessState message="Dashboard aktualisiert." /> : null}

      {stats ? (
        <View style={styles.statsGrid}>
          <StatTile label="Aktive Kurse" value={stats.activeCoursesCount} accent="#FFD166" />
          <StatTile label="Pflicht" value={stats.mandatoryCount} accent={colors.warning} />
          <StatTile label="Teilnahmen" value={stats.totalEnrollments} accent={colors.cyan} />
          <StatTile label="Anstehend" value={stats.upcomingStartsCount} accent={colors.violet} />
        </View>
      ) : null}

      <SectionPanel title="Anstehende Kurse" subtitle="Nach Starttermin sortiert">
        {upcomingCourses.length === 0 ? (
          <EmptyState
            title="Keine anstehenden Kurse"
            message="Derzeit sind keine aktiven Kurse geplant."
            actionLabel="Alle Kurse anzeigen"
            onAction={() => router.push('/akademie/courses' as never)}
          />
        ) : (
          upcomingCourses.map((course) => (
            <CourseListCard
              key={course.id}
              course={course}
              onPress={() => router.push(`/akademie/courses/${course.id}` as never)}
            />
          ))
        )}
      </SectionPanel>

      <SectionPanel title="Schnellzugriff" subtitle="Häufige Aktionen">
        <View style={styles.quickGrid}>
          <ModuleTile
            icon="🎓"
            title="Alle Kurse"
            description="Suche, Filter und Pflichtschulungen"
            accentColor="#FFD166"
            isActive
            onPress={() => router.push('/akademie/courses' as never)}
          />
          <ModuleTile
            icon="👥"
            title="Teilnehmer"
            description="Einschreibungen und Fortschritt"
            accentColor={colors.cyan}
            isActive
            onPress={() => router.push('/akademie/teilnehmer' as never)}
          />
          <ModuleTile
            icon="🏅"
            title="Zertifikate"
            description="Ausgestellte Nachweise"
            accentColor={colors.success}
            isActive
            onPress={() => router.push('/akademie/zertifikate' as never)}
          />
          <ModuleTile
            icon="📈"
            title="Auswertungen"
            description="KPIs und Kennzahlen"
            accentColor={colors.violet}
            preparedOnly
            onPress={() => router.push('/akademie/auswertungen' as never)}
          />
          <ModuleTile
            icon="⚙️"
            title="Einstellungen"
            description="Modul-Konfiguration"
            accentColor={colors.textMuted}
            preparedOnly
            onPress={() => router.push('/akademie/settings' as never)}
          />
        </View>
        {!can('akademie.courses.view') ? (
          <Text style={styles.readOnlyHint}>
            Lesemodus — Kurse sind für {roleLabel ?? 'Ihre Rolle'} nicht sichtbar.
          </Text>
        ) : null}
      </SectionPanel>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  statsGrid: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: spacing.sm,
    marginBottom: spacing.md,
  },
  statTile: { width: '47%', flexGrow: 1 },
  statValue: { ...typography.h2, marginBottom: 4 },
  statLabel: { ...typography.caption },
  quickGrid: { gap: spacing.md, marginBottom: spacing.md },
  readOnlyHint: { ...typography.caption, color: colors.textMuted },
});
