import { RefreshControl, ScrollView, StyleSheet, Text, View } from 'react-native';
import { useRouter } from 'expo-router';
import { LockedActionBanner } from '@/components/permissions';
import { PreparedModeBanner } from '@/components/modules/PreparedModeBanner';
import { ScreenShell } from '@/components/layout';
import { ErrorState, LoadingState, ModuleTile, PremiumKpiCard, SectionPanel } from '@/components/ui';
import { useQmDashboard } from '@/hooks/qm';
import { usePermissions } from '@/hooks/usePermissions';
import { colors, spacing, typography } from '@/theme';

const NAV_AREAS = [
  { id: 'handbook', icon: '📖', title: 'QM-Handbuch', route: '/business/office/qm/handbook', accent: colors.cyan },
  { id: 'documents', icon: '📄', title: 'Dokumente', route: '/business/office/qm/documents', accent: colors.orange },
  { id: 'compliance', icon: '✅', title: 'Compliance', route: '/business/office/qm/compliance', accent: colors.success },
  { id: 'md', icon: '📁', title: 'MD-Prüfung', route: '/business/office/qm/md-audit', accent: colors.violet },
  { id: 'audits', icon: '🔍', title: 'Audits', route: '/business/office/qm/audits', accent: colors.cyan },
  { id: 'measures', icon: '📋', title: 'Maßnahmen', route: '/business/office/qm/measures', accent: colors.amber },
  { id: 'changes', icon: '🔄', title: 'Änderungen', route: '/business/office/qm/changes', accent: colors.deepOrange },
  { id: 'exports', icon: '📤', title: 'Export', route: '/business/office/qm/exports', accent: colors.cyan },
  { id: 'ai', icon: '🤖', title: 'KI-Assistent', route: '/business/office/qm/ai-assistant', accent: colors.violet },
  { id: 'templates', icon: '📝', title: 'Vorlagen', route: '/business/office/qm/templates', accent: colors.orange },
  { id: 'settings', icon: '⚙️', title: 'Einstellungen', route: '/business/office/qm/settings', accent: colors.textMuted },
];

/** QM Dashboard — Office Qualitätsmanagement */
export function QmDashboardScreen() {
  const router = useRouter();
  const { can, check, roleLabel } = usePermissions();
  const { data, loading, error, refresh } = useQmDashboard();

  if (!can('qm.view')) {
    return (
      <ScreenShell title="Qualitätsmanagement" subtitle={roleLabel ?? 'Office'} showBack>
        <LockedActionBanner message={check('qm.view').reason ?? 'Keine Berechtigung.'} roleLabel={roleLabel} />
      </ScreenShell>
    );
  }

  if (loading && !data) {
    return (
      <ScreenShell title="Qualitätsmanagement" subtitle="Lädt…" showBack>
        <LoadingState message="QM-Dashboard wird geladen…" />
      </ScreenShell>
    );
  }

  if (error && !data) {
    return (
      <ScreenShell title="Qualitätsmanagement" showBack>
        <ErrorState title="QM" message={error} onRetry={refresh} />
      </ScreenShell>
    );
  }

  return (
    <ScreenShell title="Qualitätsmanagement" subtitle="Office · QM-Handbuch & MD-Prüfung" showBack>
      <ScrollView
        refreshControl={<RefreshControl refreshing={loading} onRefresh={refresh} tintColor={colors.primary} />}
        contentContainerStyle={styles.scroll}
      >
        <PreparedModeBanner hint="QM-Modul ist demo-fähig und P-READY für Live-Supabase." />
        <View style={styles.kpiRow}>
          <PremiumKpiCard label="Kapitel" value={String(data!.chapterCount)} />
          <PremiumKpiCard label="Dokumente" value={String(data!.documentCount)} />
          <PremiumKpiCard label="Compliance offen" value={String(data!.complianceOpenCount)} />
          <PremiumKpiCard label="MD-Mappen" value={String(data!.mdPackageCount)} />
          <PremiumKpiCard label="Freigaben offen" value={String(data!.pendingApprovals)} />
        </View>

        {data!.upcomingAudits.length > 0 && (
          <SectionPanel title="Anstehende Audits" subtitle={`${data!.upcomingAudits.length} geplant`}>
            {data!.upcomingAudits.map((a) => (
              <Text key={a.id} style={styles.auditItem}>• {a.title}</Text>
            ))}
          </SectionPanel>
        )}

        <SectionPanel title="Bereiche" subtitle="Qualitätsmanagement Office">
          <View style={styles.grid}>
            {NAV_AREAS.map((area) => (
              <ModuleTile
                key={area.id}
                icon={area.icon}
                title={area.title}
                description=""
                accentColor={area.accent}
                isActive
                onPress={() => router.push(area.route as never)}
              />
            ))}
          </View>
        </SectionPanel>
      </ScrollView>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  scroll: { gap: spacing.md, paddingBottom: spacing.xxl },
  kpiRow: { flexDirection: 'row', flexWrap: 'wrap', gap: spacing.sm },
  grid: { gap: spacing.md },
  auditItem: { ...typography.body, marginBottom: spacing.xs },
});
