import { StyleSheet, Text } from 'react-native';
import { LockedActionBanner } from '@/components/permissions';
import { ScreenShell } from '@/components/layout';
import { TISecurityNotice } from '@/components/ti';
import { PremiumCard } from '@/components/ui';
import { usePermissions } from '@/hooks/usePermissions';
import { colors, spacing, typography } from '@/theme';

export function ERezeptVorbereitungScreen() {
  const { can, check, roleLabel } = usePermissions();
  if (!can('ti.erezept.view')) {
    return (
      <ScreenShell title="E-Rezept-Vorbereitung">
        <LockedActionBanner message={check('ti.erezept.view').reason ?? 'Keine Berechtigung.'} roleLabel={roleLabel} />
      </ScreenShell>
    );
  }
  return (
    <ScreenShell title="E-Rezept-Vorbereitung" subtitle="Elektronisches Rezept">
      <PremiumCard accentColor={colors.cyan}>
        <Text style={styles.title}>Vorbereitung E-Rezept</Text>
        <Text style={styles.meta}>
          E-Rezept-Workflow ist teilweise verfügbar. Vollständige TI-Anbindung über gematik-konformen Connector geplant.
        </Text>
      </PremiumCard>
      <TISecurityNotice />
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  title: { ...typography.bodyStrong },
  meta: { ...typography.body, color: colors.textSecondary, marginTop: spacing.sm },
});
