import { RefreshControl, ScrollView, StyleSheet } from 'react-native';
import { LockedActionBanner } from '@/components/permissions';
import { ScreenShell } from '@/components/layout';
import { EmptyState, ErrorState, LoadingState } from '@/components/ui';
import { QmMeasureCard } from '@/components/qm';
import { useQmMeasures } from '@/hooks/qm';
import { usePermissions } from '@/hooks/usePermissions';
import { colors, spacing } from '@/theme';

export function QmMeasuresScreen() {
  const { can, check, roleLabel } = usePermissions();
  const { data, loading, error, refresh } = useQmMeasures();

  if (!can('qm.view')) {
    return (
      <ScreenShell title="Maßnahmen" showBack>
        <LockedActionBanner message={check('qm.view').reason ?? ''} roleLabel={roleLabel} />
      </ScreenShell>
    );
  }

  if (loading && !data) {
    return (
      <ScreenShell title="Maßnahmen" showBack>
        <LoadingState message="Maßnahmen werden geladen…" />
      </ScreenShell>
    );
  }

  if (error && !data) {
    return (
      <ScreenShell title="Maßnahmen" showBack>
        <ErrorState title="Maßnahmen" message={error} onRetry={refresh} />
      </ScreenShell>
    );
  }

  const items = data ?? [];

  return (
    <ScreenShell title="Maßnahmenmanagement" subtitle={`${items.length} Maßnahmen`} showBack>
      <ScrollView
        refreshControl={<RefreshControl refreshing={loading} onRefresh={refresh} tintColor={colors.primary} />}
        contentContainerStyle={styles.scroll}
      >
        {items.length === 0 ? (
          <EmptyState title="Keine Maßnahmen" message="" />
        ) : (
          items.map((m) => <QmMeasureCard key={m.id} measure={m} />)
        )}
      </ScrollView>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({ scroll: { gap: spacing.md, paddingBottom: spacing.xxl } });
