import { RefreshControl, ScrollView, StyleSheet, Text, View } from 'react-native';
import { useRouter } from 'expo-router';
import { LockedActionBanner } from '@/components/permissions';
import { ScreenShell } from '@/components/layout';
import { ErrorState, LoadingState, PremiumButton, PremiumCard, PremiumKpiCard } from '@/components/ui';
import { useRoadmapHub } from '@/hooks/useRoadmapHub';
import { usePermissions } from '@/hooks/usePermissions';
import { wp598A11y } from '@/lib/a11y/wp598-roadmap';
import { ROADMAP_PHASE_LABELS } from '@/types/roadmap';
import { colors, spacing, typography } from '@/theme';

/** WP583 — Roadmap Hub */
export function RoadmapHubScreen() {
  const router = useRouter();
  const { can, check, roleLabel } = usePermissions();
  const { data, loading, error, refresh } = useRoadmapHub();

  if (!can('roadmap.view')) {
    return (
      <ScreenShell title="Roadmap" subtitle={roleLabel ?? 'Strategie'} showBack={false} a11yMeta={wp598A11y}>
        <LockedActionBanner message={check('roadmap.view').reason ?? 'Keine Berechtigung.'} roleLabel={roleLabel} />
      </ScreenShell>
    );
  }

  if (loading && !data) return <ScreenShell title="Roadmap" showBack={false} a11yMeta={wp598A11y}><LoadingState message="Lädt…" /></ScreenShell>;
  if (error && !data) return <ScreenShell title="Roadmap" showBack={false} a11yMeta={wp598A11y}><ErrorState title="Roadmap" message={error} onRetry={refresh} /></ScreenShell>;

  return (
    <ScreenShell
      title="Strategische Roadmap"
      subtitle={`Launch-Readiness ${data!.launchReadinessPercent}%`}
      showBack={false}
      a11yMeta={wp598A11y}
      rightSlot={<PremiumButton title="Meilensteine" size="sm" variant="ghost" onPress={() => router.push('/business/roadmap/list' as never)} />}
    >
      <ScrollView refreshControl={<RefreshControl refreshing={loading} onRefresh={refresh} tintColor={colors.primary} />} contentContainerStyle={styles.scroll}>
        <View style={styles.kpiRow}>
          {data!.kpis.map((kpi) => <PremiumKpiCard key={kpi.id} label={kpi.label} value={String(kpi.value)} subValue={kpi.subValue} />)}
        </View>
        {data!.phases.map((p) => (
          <PremiumCard key={p.phase} accentColor={colors.violet}>
            <Text style={styles.title}>{ROADMAP_PHASE_LABELS[p.phase]}</Text>
            <Text style={styles.meta}>{p.count} Meilenstein(e)</Text>
          </PremiumCard>
        ))}
        <PremiumButton title="Meilenstein anlegen" onPress={() => router.push('/business/roadmap/create' as never)} disabled={!can('roadmap.manage')} />
        <PremiumButton title="Live-Pilot Readiness" variant="secondary" onPress={() => router.push('/business/roadmap/pilot-readiness' as never)} />
      </ScrollView>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  scroll: { gap: spacing.md, paddingBottom: spacing.xxl },
  kpiRow: { flexDirection: 'row', flexWrap: 'wrap', gap: spacing.sm },
  title: { ...typography.bodyStrong },
  meta: { ...typography.caption, color: colors.textSecondary },
});
