import { RefreshControl, ScrollView, StyleSheet, Text, View } from 'react-native';
import { ScreenShell } from '@/components/layout';
import {
  EmptyState,
  ErrorState,
  LoadingState,
  PremiumBadge,
  PremiumCard,
} from '@/components/ui';
import { useAiJobList } from '@/hooks/useAiJobList';
import { AI_JOB_TYPE_LABELS } from '@/types/modules/platform';
import { WORKFLOW_STATUS_LABELS } from '@/types/workflow/status';
import { colors, spacing, typography } from '@/theme';

export function AiJobsListScreen() {
  const { items, loading, error, refresh } = useAiJobList();

  return (
    <ScreenShell title="KI-Jobs" subtitle="OpenAI (Demo)" showBack={false}>
      {loading && items.length === 0 ? (
        <LoadingState message="KI-Jobs werden geladen…" />
      ) : error && items.length === 0 ? (
        <ErrorState title="Fehler" message={error} onRetry={refresh} />
      ) : (
        <ScrollView
          refreshControl={
            <RefreshControl refreshing={loading} onRefresh={refresh} tintColor={colors.primary} />
          }
          contentContainerStyle={styles.scroll}
        >
          {items.length === 0 ? (
            <EmptyState title="Keine Jobs" message="Noch keine KI-Verarbeitungen." />
          ) : (
            items.map((job) => (
              <PremiumCard key={job.id} accentColor={colors.primary}>
                <View style={styles.row}>
                  <Text style={styles.title}>{job.promptSummary}</Text>
                  <PremiumBadge label={WORKFLOW_STATUS_LABELS[job.status]} variant="muted" />
                </View>
                <Text style={styles.meta}>{AI_JOB_TYPE_LABELS[job.jobType]}</Text>
                {job.resultSummary ? (
                  <Text style={styles.result} numberOfLines={3}>
                    {job.resultSummary}
                  </Text>
                ) : null}
              </PremiumCard>
            ))
          )}
        </ScrollView>
      )}
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  scroll: { gap: spacing.md, paddingBottom: spacing.xxl },
  row: { flexDirection: 'row', justifyContent: 'space-between', gap: spacing.sm, marginBottom: spacing.xs },
  title: { ...typography.bodyStrong, flex: 1 },
  meta: { ...typography.caption, color: colors.textSecondary },
  result: { ...typography.body, color: colors.textSecondary, marginTop: spacing.xs },
});
