import { FlatList, RefreshControl, StyleSheet, Text, View } from 'react-native';
import { useRouter } from 'expo-router';
import { CourseListCard } from '@/components/akademie';
import { ScreenShell } from '@/components/layout';
import {
  EmptyState,
  ErrorState,
  FilterChipGroup,
  LoadingState,
  PremiumButton,
  PremiumInput,
  SuccessState,
} from '@/components/ui';
import { useCourseList } from '@/hooks/useCourseList';
import { usePermissions } from '@/hooks/usePermissions';
import { colors, spacing, typography } from '@/theme';

export function CoursesListScreen() {
  const router = useRouter();
  const { roleLabel } = usePermissions();
  const {
    items,
    totalCount,
    filteredCount,
    loading,
    error,
    refreshing,
    showSuccess,
    search,
    setSearch,
    statusFilter,
    setStatusFilter,
    sortKey,
    setSortKey,
    sortOptions,
    statusFilters,
    hasMore,
    loadMore,
    refresh,
    resetFilters,
    hasActiveFilters,
    isEmpty,
    isFilterEmpty,
  } = useCourseList();

  const header = (
    <View style={styles.toolbar}>
      {showSuccess ? <SuccessState message="Liste erfolgreich aktualisiert." /> : null}

      <PremiumInput
        label="Suche"
        placeholder="Titel oder Kategorie…"
        value={search}
        onChangeText={setSearch}
        autoCapitalize="words"
        autoCorrect={false}
        hint={`${filteredCount} von ${totalCount} Kursen`}
      />

      <Text style={styles.filterLabel}>Status</Text>
      <FilterChipGroup options={statusFilters} value={statusFilter} onChange={setStatusFilter} />

      <Text style={styles.filterLabel}>Sortierung</Text>
      <FilterChipGroup options={sortOptions} value={sortKey} onChange={setSortKey} />
    </View>
  );

  if (loading && items.length === 0) {
    return (
      <ScreenShell title="Kurse" subtitle="Wird geladen…">
        <LoadingState message="Kurse werden geladen…" />
      </ScreenShell>
    );
  }

  if (error && items.length === 0 && totalCount === 0) {
    return (
      <ScreenShell title="Kurse" subtitle="Fehler">
        <ErrorState message={error} onRetry={refresh} />
      </ScreenShell>
    );
  }

  return (
    <ScreenShell
      title="Kurse"
      subtitle={`${filteredCount} Einträge · ${roleLabel ?? 'Demo'}`}
      scroll={false}
    >
      <FlatList
        style={styles.flatList}
        data={items}
        keyExtractor={(item) => item.id}
        ListHeaderComponent={header}
        ListEmptyComponent={
          isEmpty ? (
            <EmptyState
              title="Noch keine Kurse"
              message="Es sind keine Kurse im Demo-Mandanten hinterlegt."
            />
          ) : isFilterEmpty ? (
            <EmptyState
              title="Keine Treffer"
              message="Für Ihre Suche oder Filter wurden keine Kurse gefunden."
              actionLabel="Filter zurücksetzen"
              onAction={resetFilters}
            />
          ) : null
        }
        ListFooterComponent={
          hasMore ? (
            <PremiumButton
              title="Weitere laden"
              variant="secondary"
              fullWidth
              onPress={loadMore}
              style={styles.loadMore}
            />
          ) : filteredCount > 0 ? (
            <Text style={styles.footer}>
              {filteredCount} Kurse angezeigt
              {hasActiveFilters ? ' (gefiltert)' : ''}
            </Text>
          ) : null
        }
        renderItem={({ item }) => (
          <CourseListCard
            course={item}
            onPress={() => router.push(`/akademie/courses/${item.id}` as never)}
          />
        )}
        contentContainerStyle={styles.list}
        showsVerticalScrollIndicator={false}
        refreshControl={
          <RefreshControl refreshing={refreshing} onRefresh={refresh} tintColor={colors.primary} />
        }
      />
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  flatList: { flex: 1 },
  toolbar: { gap: spacing.sm, marginBottom: spacing.md },
  filterLabel: { ...typography.label, marginTop: spacing.xs },
  list: { paddingBottom: spacing.xxl },
  loadMore: { marginTop: spacing.sm, marginBottom: spacing.md },
  footer: { ...typography.caption, textAlign: 'center', marginVertical: spacing.md },
});
