import { FlatList, RefreshControl, StyleSheet, Text, View } from 'react-native';
import { useRouter } from 'expo-router';
import { LockedActionBanner } from '@/components/permissions';
import {
  ConversationFilterBar,
  ConversationListItem,
  MessageSearchBar,
} from '@/components/communication';
import { ScreenShell } from '@/components/layout';
import {
  EmptyState,
  ErrorState,
  LoadingState,
  PremiumBadge,
  PremiumButton,
  PremiumCard,
} from '@/components/ui';
import { COMMUNICATION_ACCENT } from '@/features/communication/communication.constants';
import {
  useCommunicationCenter,
  useCommunicationPermissions,
} from '@/hooks/communication';
import { colors, spacing, typography } from '@/theme';

export function CommunicationCenterScreen({
  onThreadPress,
  embedded = false,
}: {
  onThreadPress?: (threadId: string) => void;
  embedded?: boolean;
} = {}) {
  const router = useRouter();
  const perms = useCommunicationPermissions();
  const {
    threads,
    kpis,
    loading,
    error,
    refreshing,
    filter,
    setFilter,
    filters,
    search,
    setSearch,
    refresh,
    demoMode,
  } = useCommunicationCenter();

  if (!perms.canViewCenter) {
    return (
      <ScreenShell title="Nachrichten" subtitle="Kommunikationszentrum">
        <LockedActionBanner message="Keine Berechtigung für das Kommunikationszentrum." />
      </ScreenShell>
    );
  }

  const header = (
    <View style={styles.header}>
      <Text style={styles.intro}>
        Zentrale Kommunikation mit Klient:innen, Mitarbeitenden, Angehörigen und internen Teams.
      </Text>
      <PremiumBadge
        label={demoMode ? 'Demo-Modus' : 'Realtime bereit'}
        variant="cyan"
      />
      <PremiumButton
        title="Neue Nachricht"
        onPress={() => router.push('/business/messages/new' as never)}
      />
      {kpis ? (
        <View style={styles.kpiRow}>
          {[
            ['Ungelesen', kpis.unread],
            ['Offen', kpis.openQuestions],
            ['Nicht zugeordnet', kpis.unassigned],
            ['Archiviert', kpis.archived],
            ['Anhänge', kpis.withAttachments],
            ['Fehler', kpis.failedDeliveries],
          ].map(([label, value]) => (
            <PremiumCard key={label} accentColor={COMMUNICATION_ACCENT} style={styles.kpiCard}>
              <Text style={styles.kpiValue}>{value}</Text>
              <Text style={styles.kpiLabel}>{label}</Text>
            </PremiumCard>
          ))}
        </View>
      ) : null}
      <MessageSearchBar value={search} onChangeText={setSearch} placeholder="Name, Betreff, Text…" />
      <ConversationFilterBar filter={filter} onChange={setFilter} filters={filters} />
      <View style={styles.links}>
        <PremiumButton
          title="Archiviert"
          size="sm"
          variant="secondary"
          onPress={() => router.push('/business/messages/archived' as never)}
        />
        <PremiumButton
          title="Zuordnungen"
          size="sm"
          variant="secondary"
          onPress={() => router.push('/business/messages/assignments' as never)}
        />
        <PremiumButton
          title="Einstellungen"
          size="sm"
          variant="ghost"
          onPress={() => router.push('/business/messages/settings' as never)}
        />
      </View>
    </View>
  );

  if (loading && threads.length === 0) {
    return (
      <ScreenShell title="Nachrichten" subtitle="Kommunikationszentrum" showBack={false}>
        <LoadingState message="Threads werden geladen…" />
      </ScreenShell>
    );
  }

  if (error && threads.length === 0) {
    return (
      <ScreenShell title="Nachrichten" subtitle="Kommunikationszentrum" showBack={false}>
        <ErrorState message={error} onRetry={refresh} />
      </ScreenShell>
    );
  }

  return (
    <ScreenShell title="Nachrichten" subtitle="Kommunikationszentrum" showBack={embedded ? false : undefined} scroll={false}>
      <FlatList
        data={threads}
        keyExtractor={(item) => item.id}
        ListHeaderComponent={header}
        refreshControl={
          <RefreshControl refreshing={refreshing} onRefresh={refresh} tintColor={colors.cyan} />
        }
        contentContainerStyle={styles.list}
        ListEmptyComponent={
          <EmptyState title="Keine Threads" message="Passen Sie Filter oder Suche an." onAction={refresh} />
        }
        renderItem={({ item }) => (
          <PremiumCard
            accentColor={item.unreadCountBusiness > 0 ? colors.cyan : undefined}
            onPress={() => {
              if (onThreadPress) {
                onThreadPress(item.id);
                return;
              }
              router.push(`/business/messages/${item.id}` as never);
            }}
          >
            <ConversationListItem item={item} />
          </PremiumCard>
        )}
      />
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  header: { gap: spacing.md, paddingBottom: spacing.md },
  intro: { ...typography.body, color: colors.textSecondary },
  kpiRow: { flexDirection: 'row', flexWrap: 'wrap', gap: spacing.sm },
  kpiCard: { minWidth: '30%', flexGrow: 1 },
  kpiValue: { ...typography.h3, color: colors.cyan },
  kpiLabel: { ...typography.caption, color: colors.textMuted },
  links: { flexDirection: 'row', flexWrap: 'wrap', gap: spacing.sm },
  list: { gap: spacing.md, paddingBottom: spacing.xxl },
});
