import { useMemo, useState } from 'react';
import { Pressable, RefreshControl, ScrollView, StyleSheet, Text, View } from 'react-native';
import { useRouter } from 'expo-router';
import { DetailInfoRow } from '@/components/detail';
import { LockedActionBanner } from '@/components/permissions';
import { ScreenShell } from '@/components/layout';
import {
  ErrorState,
  LoadingState,
  PremiumBadge,
  PremiumButton,
  PremiumCard,
  PremiumInput,
  PremiumKpiCard,
  SectionPanel,
  SegmentedTabs,
} from '@/components/ui';
import { useSubscription } from '@/hooks/useSubscription';
import { usePermissions } from '@/hooks/usePermissions';
import {
  calculateCartTotal,
  formatPriceEur,
  TRIAL_DAYS,
  type PackageKey,
} from '@/lib/billing';
import { resolvePackageModules } from '@/lib/billing/pricingCatalog';
import { colors, radius, spacing, typography } from '@/theme';

function formatDate(iso: string): string {
  return new Date(iso).toLocaleDateString('de-DE', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  });
}

const STATUS_LABELS: Record<string, string> = {
  trialing: 'Testphase',
  active: 'Aktiv',
  past_due: 'Überfällig',
  canceled: 'Gekündigt',
  inactive: 'Inaktiv',
};

export function SubscriptionScreen() {
  const router = useRouter();
  const { can, check, roleLabel } = usePermissions();
  const {
    data,
    loading,
    error,
    refresh,
    cartPreview,
    cartOptions,
    updateCartOptions,
    previewModuleCart,
    resetCartPreview,
  } = useSubscription();

  const [promoInput, setPromoInput] = useState('');
  const [selectedPackageKey, setSelectedPackageKey] = useState<PackageKey | null>(null);

  const displayCart = useMemo(() => {
    if (selectedPackageKey) {
      return calculateCartTotal(resolvePackageModules(selectedPackageKey), {
        ...cartOptions,
        packageKey: selectedPackageKey,
      });
    }
    return cartPreview;
  }, [selectedPackageKey, cartOptions, cartPreview]);

  const handlePackageSelect = (packageKey: PackageKey) => {
    setSelectedPackageKey(packageKey);
    previewModuleCart(resolvePackageModules(packageKey), { ...cartOptions, packageKey });
  };

  const handleApplyPromo = () => {
    updateCartOptions({ promoCode: promoInput.trim() || null });
    if (selectedPackageKey) {
      previewModuleCart(resolvePackageModules(selectedPackageKey), {
        ...cartOptions,
        promoCode: promoInput.trim() || null,
        packageKey: selectedPackageKey,
      });
    }
  };

  if (!can('business.subscription.view')) {
    return (
      <ScreenShell title="Abonnement" subtitle={roleLabel ?? 'Business'} showBack={false}>
        <LockedActionBanner
          message={check('business.subscription.view').reason ?? 'Keine Berechtigung.'}
          roleLabel={roleLabel}
        />
      </ScreenShell>
    );
  }

  if (loading && !data) {
    return (
      <ScreenShell title="Abonnement" subtitle="Wird geladen…" showBack={false}>
        <LoadingState message="Abonnement wird geladen…" />
      </ScreenShell>
    );
  }

  if (error && !data) {
    return (
      <ScreenShell title="Abonnement" subtitle="Fehler" showBack={false}>
        <ErrorState title="Fehler" message={error} onRetry={refresh} />
      </ScreenShell>
    );
  }

  if (!data) return null;

  const interval = cartOptions.billingInterval ?? 'monthly';
  const displayTotal =
    interval === 'annual'
      ? displayCart?.totalAnnual ?? 0
      : displayCart?.totalMonthly ?? data.monthlyTotal;

  return (
    <ScreenShell title="Abonnement" subtitle={data.tenantName} showBack={false}>
      <ScrollView
        refreshControl={
          <RefreshControl refreshing={loading} onRefresh={refresh} tintColor={colors.primary} />
        }
        contentContainerStyle={styles.scroll}
      >
        <PremiumCard accentColor={colors.cyan}>
          <View style={styles.headerRow}>
            <Text style={styles.plan}>{data.planLabel}</Text>
            <View style={styles.badgeRow}>
              <PremiumBadge label={`${TRIAL_DAYS} Tage Testphase`} variant="orange" />
              <PremiumBadge label={STATUS_LABELS[data.status] ?? data.status} variant="cyan" />
            </View>
          </View>
          <DetailInfoRow label="Mandant" value={data.tenantName} />
          <DetailInfoRow
            label="Abrechnungszeitraum"
            value={
              data.currentPeriodStart && data.currentPeriodEnd
                ? `${formatDate(data.currentPeriodStart)} – ${formatDate(data.currentPeriodEnd)}`
                : '—'
            }
          />
        </PremiumCard>

        <View style={styles.kpiRow}>
          <PremiumKpiCard
            label="Module"
            value={data.moduleCount}
            subValue={`${data.billableModuleCount} abrechenbar · ${data.includedModuleCount} inklusive`}
          />
          <PremiumKpiCard
            label="Testphase"
            value={data.trialDaysLeft != null ? `${data.trialDaysLeft} Tage` : '—'}
            subValue={data.trialEndsAt ? `bis ${formatDate(data.trialEndsAt)}` : undefined}
            accentColor={colors.orange}
          />
        </View>

        <SectionPanel
          title="Pakete & Preise"
          subtitle="Monatliche Nettopreise — ohne Einrichtungsgebühr im Startangebot"
        >
          <View style={styles.packageList}>
            {data.publicPackages.map((pkg) => {
              const selected = selectedPackageKey === pkg.key;
              return (
                <Pressable
                  key={pkg.key}
                  onPress={() => handlePackageSelect(pkg.key)}
                  style={({ pressed }) => [
                    styles.packageRow,
                    selected && styles.packageRowSelected,
                    pressed && styles.packageRowPressed,
                  ]}
                >
                  <View style={styles.packageText}>
                    <Text style={styles.packageTitle}>{pkg.publicLabel}</Text>
                    <Text style={styles.packageDesc}>{pkg.description}</Text>
                    {pkg.key !== 'office_solo' && pkg.key !== 'enterprise' ? (
                      <Text style={styles.includedHint}>Office inklusive</Text>
                    ) : null}
                  </View>
                  <Text style={styles.packagePrice}>
                    {pkg.isContactSales
                      ? 'auf Anfrage'
                      : formatPriceEur(pkg.monthlyNetEur ?? 0)}
                  </Text>
                </Pressable>
              );
            })}
          </View>
        </SectionPanel>

        <SectionPanel title="Abrechnungszeitraum" subtitle="Jährlich: 2 Monate gratis (10 Monate zahlen)">
          <SegmentedTabs
            tabs={[
              { key: 'monthly', label: 'Monatlich' },
              { key: 'annual', label: 'Jährlich (−17 %)' },
            ]}
            activeKey={interval}
            onSelect={(key) => updateCartOptions({ billingInterval: key as 'monthly' | 'annual' })}
          />
        </SectionPanel>

        {displayCart ? (
          <SectionPanel title="Warenkorb-Vorschau" subtitle="Demo — keine echte Zahlung">
            <View style={styles.cartLines}>
              {displayCart.lineItems.map((line, index) => (
                <View key={`${line.label}-${index}`} style={styles.cartLine}>
                  <Text style={styles.cartLabel}>{line.label}</Text>
                  <Text
                    style={[
                      styles.cartAmount,
                      line.type === 'included' && styles.cartIncluded,
                      line.type === 'discount' && styles.cartDiscount,
                    ]}
                  >
                    {line.type === 'included'
                      ? 'Inklusive'
                      : formatPriceEur(Math.abs(line.amount), 'monthly')}
                  </Text>
                </View>
              ))}
            </View>
            <View style={styles.cartTotalRow}>
              <Text style={styles.cartTotalLabel}>
                {interval === 'annual' ? 'Jährlich (10 Monate)' : 'Monatlich netto'}
              </Text>
              <Text style={styles.cartTotalValue}>{formatPriceEur(displayTotal, interval)}</Text>
            </View>
            {interval === 'annual' && displayCart.totalMonthly > 0 ? (
              <Text style={styles.savingsHint}>
                Entspricht {formatPriceEur(displayCart.effectiveMonthlyWithInterval)}/Monat
              </Text>
            ) : null}
          </SectionPanel>
        ) : null}

        <SectionPanel title="Promo-Code" subtitle="Demo-Store: ISR10050 = 50 % für 6 Monate">
          <PremiumInput
            label="Code"
            placeholder="z. B. ISR10050"
            value={promoInput}
            onChangeText={setPromoInput}
            autoCapitalize="characters"
          />
          <PremiumButton title="Code anwenden" variant="secondary" size="sm" onPress={handleApplyPromo} />
        </SectionPanel>

        {data.includedModuleCount > 0 ? (
          <PremiumCard>
            <Text style={styles.includedTitle}>Enthaltene Basisverwaltung</Text>
            <Text style={styles.includedText}>
              CareSuite+ Office ist als Basisverwaltung automatisch enthalten, wenn ein Fachmodul
              gebucht ist ({data.includedModuleCount} Modul{data.includedModuleCount === 1 ? '' : 'e'} ohne
              Zusatzabrechnung).
            </Text>
          </PremiumCard>
        ) : null}

        <Text style={styles.footerNote}>
          CareSuite+ Office ist in jedem Fachmodul automatisch enthalten.
        </Text>

        {can('integrations.view') ? (
          <PremiumButton
            title="Integrationen verwalten"
            variant="secondary"
            onPress={() => router.push('/business/integrations' as never)}
          />
        ) : null}

        {selectedPackageKey ? (
          <PremiumButton
            title="Paketauswahl zurücksetzen"
            variant="secondary"
            onPress={() => {
              setSelectedPackageKey(null);
              resetCartPreview();
            }}
          />
        ) : null}

        {!can('business.subscription.manage') ? (
          <Text style={styles.hint}>
            Planänderungen sind im Demo-Modus schreibgeschützt.
          </Text>
        ) : null}
      </ScrollView>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  scroll: { gap: spacing.md, paddingBottom: spacing.xxl },
  headerRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'flex-start',
    marginBottom: spacing.sm,
    gap: spacing.sm,
  },
  badgeRow: { flexDirection: 'row', flexWrap: 'wrap', gap: spacing.xs, maxWidth: '55%' },
  plan: { ...typography.h3, flex: 1 },
  kpiRow: { flexDirection: 'row', gap: spacing.sm },
  packageList: { gap: spacing.sm },
  packageRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: spacing.sm,
    padding: spacing.md,
    borderRadius: radius.md,
    borderWidth: 1,
    borderColor: colors.borderSoft,
    backgroundColor: colors.bgSurface,
  },
  packageRowSelected: {
    borderColor: colors.cyan,
    backgroundColor: 'rgba(0,188,212,0.08)',
  },
  packageRowPressed: { opacity: 0.9 },
  packageText: { flex: 1, gap: 2 },
  packageTitle: { ...typography.bodyStrong },
  packageDesc: { ...typography.caption, color: colors.textSecondary },
  includedHint: { ...typography.caption, color: colors.cyan, marginTop: 2 },
  packagePrice: { ...typography.bodyStrong, color: colors.cyan },
  cartLines: { gap: spacing.xs, marginBottom: spacing.sm },
  cartLine: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    paddingVertical: spacing.xs,
  },
  cartLabel: { ...typography.body, flex: 1 },
  cartAmount: { ...typography.bodyStrong },
  cartIncluded: { ...typography.caption, color: colors.textSecondary },
  cartDiscount: { color: colors.success },
  cartTotalRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    borderTopWidth: 1,
    borderTopColor: colors.borderSoft,
    paddingTop: spacing.sm,
    marginTop: spacing.xs,
  },
  cartTotalLabel: { ...typography.bodyStrong },
  cartTotalValue: { ...typography.h3, color: colors.cyan },
  savingsHint: { ...typography.caption, color: colors.textSecondary, marginTop: spacing.xs },
  hint: { ...typography.caption, color: colors.textSecondary, textAlign: 'center' },
  includedTitle: { ...typography.bodyStrong, marginBottom: spacing.xs },
  includedText: { ...typography.caption, color: colors.textSecondary },
  footerNote: {
    ...typography.caption,
    color: colors.textSecondary,
    textAlign: 'center',
    fontStyle: 'italic',
  },
});
