import { useState } from 'react';
import { MasterDetailLayout } from '@/components/layout';
import { usePlatformLayout } from '@/hooks/platform/usePlatformLayout';
import { CommunicationCenterScreen } from './CommunicationCenterScreen';
import { ConversationScreen } from './ConversationScreen';

export function CommunicationAdaptiveScreen() {
  const { useMasterDetail } = usePlatformLayout();
  const [selectedThreadId, setSelectedThreadId] = useState<string | null>(null);

  if (!useMasterDetail) {
    return <CommunicationCenterScreen />;
  }

  return (
    <MasterDetailLayout
      master={
        <CommunicationCenterScreen embedded onThreadPress={setSelectedThreadId} />
      }
      detail={
        selectedThreadId ? (
          <ConversationScreen threadId={selectedThreadId} embedded />
        ) : (
          <></>
        )
      }
      showDetail={!!selectedThreadId}
    />
  );
}
