import { ScrollView, StyleSheet, View } from 'react-native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { DetailInfoRow } from '@/components/detail';
import { ScreenShell } from '@/components/layout';
import { LockedActionBanner } from '@/components/permissions';
import {
  ErrorState,
  LoadingState,
  PremiumBadge,
  PremiumButton,
  PremiumCard,
  SectionPanel,
} from '@/components/ui';
import { useEmployeeDetail } from '@/hooks/useEmployeeDetail';
import { usePermissions } from '@/hooks/usePermissions';
import { WORKFLOW_STATUS_LABELS } from '@/types/workflow/status';
import { colors, spacing } from '@/theme';

export function EmployeeDetailScreen() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const router = useRouter();
  const { can, check, roleLabel } = usePermissions();
  const canView = can('office.employees.view');
  const { data: employee, loading, error, refresh, notFound } = useEmployeeDetail(id);

  if (!canView) {
    return (
      <ScreenShell title="Mitarbeitende:r" subtitle="Kein Zugriff">
        <LockedActionBanner
          message={check('office.employees.view').reason ?? 'Keine Berechtigung.'}
          roleLabel={roleLabel}
        />
      </ScreenShell>
    );
  }

  if (loading) {
    return (
      <ScreenShell title="Mitarbeitende:r" subtitle="Wird geladen…">
        <LoadingState message="Detaildaten werden geladen…" />
      </ScreenShell>
    );
  }

  if (notFound || error) {
    return (
      <ScreenShell title="Mitarbeitende:r" subtitle="Fehler">
        <ErrorState
          title={notFound ? 'Nicht gefunden' : 'Fehler'}
          message={error ?? 'Der Datensatz existiert nicht.'}
          onRetry={refresh}
        />
        <PremiumButton title="Zur Liste" variant="secondary" onPress={() => router.back()} />
      </ScreenShell>
    );
  }

  if (!employee) return null;

  const fullName = `${employee.firstName} ${employee.lastName}`;

  const canEdit = can('office.employees.edit');

  return (
    <ScreenShell
      title={fullName}
      subtitle="Mitarbeitenden-Details"
      rightSlot={
        canEdit ? (
          <PremiumButton
            title="Bearbeiten"
            size="sm"
            variant="ghost"
            onPress={() => router.push(`/office/employees/${id}/edit` as never)}
          />
        ) : undefined
      }
    >
      <ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={styles.scroll}>
        <PremiumCard accentColor={colors.cyan}>
          <View style={styles.badgeRow}>
            <PremiumBadge
              label={WORKFLOW_STATUS_LABELS[employee.status]}
              variant={employee.status === 'aktiv' ? 'green' : 'muted'}
              dot
            />
            {employee.jobTitle ? (
              <PremiumBadge label={employee.jobTitle} variant="cyan" />
            ) : null}
          </View>
        </PremiumCard>

        <SectionPanel title="Kontakt">
          <DetailInfoRow label="E-Mail" value={employee.email} />
          <DetailInfoRow label="Telefon" value={employee.phone} />
        </SectionPanel>

        <SectionPanel title="Anstellung">
          <DetailInfoRow label="Abteilung" value={employee.department} />
          <DetailInfoRow
            label="Eintrittsdatum"
            value={
              employee.startDate
                ? new Date(employee.startDate).toLocaleDateString('de-DE')
                : null
            }
          />
          <DetailInfoRow
            label="Angelegt am"
            value={new Date(employee.createdAt).toLocaleDateString('de-DE')}
          />
          {employee.notes ? <DetailInfoRow label="Hinweise" value={employee.notes} /> : null}
        </SectionPanel>
      </ScrollView>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  scroll: { paddingBottom: spacing.xxl, gap: spacing.md },
  badgeRow: { flexDirection: 'row', flexWrap: 'wrap', gap: spacing.sm },
});
