import { FlatList, RefreshControl, StyleSheet, Text, View } from 'react-native';
import { ScreenShell } from '@/components/layout';
import {
  EmptyState,
  ErrorState,
  FilterChipGroup,
  LoadingState,
  PremiumBadge,
  PremiumButton,
  PremiumCard,
  PremiumInput,
  SuccessState,
} from '@/components/ui';
import { useOfficeDocuments } from '@/hooks/useOfficeDocuments';
import { usePermissions } from '@/hooks/usePermissions';
import { formatFileSize } from '@/lib/portal';
import { PORTAL_DOCUMENT_CATEGORY_LABELS } from '@/types/portal/documents';
import { SENSITIVITY_LABELS, VISIBILITY_LABELS } from '@/types/portal/visibility';
import { WORKFLOW_STATUS_LABELS } from '@/types/workflow/status';
import { colors, spacing, typography } from '@/theme';

function formatDate(iso: string): string {
  return new Date(iso).toLocaleDateString('de-DE', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  });
}

export function OfficeDocumentsListScreen() {
  const { can, roleLabel } = usePermissions();
  const canView = can('office.documents.view');
  const {
    items,
    totalCount,
    filteredCount,
    loading,
    error,
    refreshing,
    showSuccess,
    search,
    setSearch,
    statusFilter,
    setStatusFilter,
    sortKey,
    setSortKey,
    sortOptions,
    statusFilters,
    hasMore,
    loadMore,
    refresh,
    resetFilters,
    hasActiveFilters,
    isEmpty,
    isFilterEmpty,
  } = useOfficeDocuments();

  const header = (
    <View style={styles.toolbar}>
      {showSuccess ? <SuccessState message="Dokumente erfolgreich aktualisiert." /> : null}

      <PremiumInput
        label="Suche"
        placeholder="Titel oder Dateiname…"
        value={search}
        onChangeText={setSearch}
        autoCorrect={false}
        hint={`${filteredCount} von ${totalCount} Dokumenten`}
      />

      <Text style={styles.filterLabel}>Status</Text>
      <FilterChipGroup options={statusFilters} value={statusFilter} onChange={setStatusFilter} />

      <Text style={styles.filterLabel}>Sortierung</Text>
      <FilterChipGroup options={sortOptions} value={sortKey} onChange={setSortKey} />
    </View>
  );

  if (!canView) {
    return (
      <ScreenShell title="Dokumente" subtitle="Kein Zugriff">
        <EmptyState
          title="Zugriff verweigert"
          message={`Office-Dokumente sind für ${roleLabel ?? 'Ihre Rolle'} nicht freigegeben.`}
        />
      </ScreenShell>
    );
  }

  if (loading && items.length === 0) {
    return (
      <ScreenShell title="Dokumente" subtitle="Wird geladen…">
        <LoadingState message="Office-Dokumente werden geladen…" />
      </ScreenShell>
    );
  }

  if (error && items.length === 0 && totalCount === 0) {
    return (
      <ScreenShell title="Dokumente" subtitle="Fehler">
        <ErrorState message={error} onRetry={refresh} />
      </ScreenShell>
    );
  }

  return (
    <ScreenShell title="Dokumente" subtitle={`${filteredCount} Einträge`} scroll={false}>
      <FlatList
        style={styles.flatList}
        data={items}
        keyExtractor={(item) => item.id}
        ListHeaderComponent={header}
        ListEmptyComponent={
          isEmpty ? (
            <EmptyState
              title="Noch keine Dokumente"
              message="Es sind keine Office-Dokumente im Demo-Mandanten vorhanden."
            />
          ) : isFilterEmpty ? (
            <EmptyState
              title="Keine Treffer"
              message="Für Ihre Suche oder Filter wurden keine Dokumente gefunden."
              actionLabel="Filter zurücksetzen"
              onAction={resetFilters}
            />
          ) : null
        }
        ListFooterComponent={
          hasMore ? (
            <PremiumButton
              title="Weitere laden"
              variant="secondary"
              fullWidth
              onPress={loadMore}
              style={styles.loadMore}
            />
          ) : filteredCount > 0 ? (
            <Text style={styles.footer}>
              {filteredCount} Dokumente angezeigt
              {hasActiveFilters ? ' (gefiltert)' : ''}
            </Text>
          ) : null
        }
        renderItem={({ item }) => (
          <PremiumCard accentColor={colors.orange}>
            <View style={styles.cardHeader}>
              <Text style={styles.title}>{item.title}</Text>
              <PremiumBadge
                label={PORTAL_DOCUMENT_CATEGORY_LABELS[item.category]}
                variant="muted"
              />
            </View>
            <Text style={styles.fileName}>{item.fileName}</Text>
            <Text style={styles.meta}>
              {formatFileSize(item.fileSizeBytes)} · {formatDate(item.updatedAt)}
            </Text>
            <View style={styles.badges}>
              <PremiumBadge
                label={WORKFLOW_STATUS_LABELS[item.status]}
                variant={item.status === 'fehlerhaft' ? 'red' : 'muted'}
              />
              <PremiumBadge label={VISIBILITY_LABELS[item.visibility]} variant="cyan" />
              <PremiumBadge
                label={SENSITIVITY_LABELS[item.sensitivity]}
                variant={item.sensitivity === 'restricted' ? 'red' : 'muted'}
              />
            </View>
          </PremiumCard>
        )}
        contentContainerStyle={styles.list}
        showsVerticalScrollIndicator={false}
        refreshControl={
          <RefreshControl refreshing={refreshing} onRefresh={refresh} tintColor={colors.primary} />
        }
      />
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  flatList: { flex: 1 },
  toolbar: { gap: spacing.sm, marginBottom: spacing.md },
  filterLabel: { ...typography.label, marginTop: spacing.xs },
  list: { paddingBottom: spacing.xxl, gap: spacing.sm },
  loadMore: { marginTop: spacing.sm, marginBottom: spacing.md },
  footer: { ...typography.caption, textAlign: 'center', marginVertical: spacing.md },
  cardHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'flex-start',
    gap: spacing.sm,
    marginBottom: spacing.xs,
  },
  title: { ...typography.bodyStrong, flex: 1 },
  fileName: { ...typography.caption, color: colors.textSecondary },
  meta: { ...typography.caption, marginTop: spacing.xs },
  badges: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: spacing.xs,
    marginTop: spacing.sm,
  },
});
