import { StyleSheet, Text, View } from 'react-native';
import { useRouter } from 'expo-router';
import { AssignmentListCard } from '@/components/assist';
import { ScreenShell } from '@/components/layout';
import {
  EmptyState,
  ErrorState,
  LoadingState,
  ModuleTile,
  PremiumButton,
  PremiumCard,
  SectionPanel,
  SuccessState,
} from '@/components/ui';
import { useAssistDashboard } from '@/hooks/useAssistDashboard';
import { usePermissions } from '@/hooks/usePermissions';
import { wp258A11y } from '@/lib/a11y/wp258-assist-planning';
import { colors, spacing, typography } from '@/theme';

function StatTile({ label, value, accent }: { label: string; value: number; accent: string }) {
  return (
    <PremiumCard style={styles.statTile} accentColor={accent}>
      <Text style={styles.statValue}>{value}</Text>
      <Text style={styles.statLabel}>{label}</Text>
    </PremiumCard>
  );
}

export function AssistIndexScreen() {
  const router = useRouter();
  const { can, roleLabel } = usePermissions();
  const {
    stats,
    todayAssignments,
    loading,
    error,
    showSuccess,
    refresh,
  } = useAssistDashboard();

  if (loading && !stats) {
    return (
      <ScreenShell title="CareSuite+ Assist" subtitle="Einsatzplanung">
        <LoadingState message="Dashboard wird geladen…" />
      </ScreenShell>
    );
  }

  if (error && !stats) {
    return (
      <ScreenShell title="CareSuite+ Assist" subtitle="Fehler">
        <ErrorState message={error} onRetry={refresh} />
      </ScreenShell>
    );
  }

  return (
    <ScreenShell title="CareSuite+ Assist" subtitle={`Einsatzplanung · ${roleLabel ?? 'Demo'}`} a11yMeta={wp258A11y}>
      {showSuccess ? <SuccessState message="Dashboard aktualisiert." /> : null}

      {stats ? (
        <View style={styles.statsGrid}>
          <StatTile label="Heute" value={stats.todayCount} accent={colors.amber} />
          <StatTile label="Aktiv" value={stats.activeCount} accent={colors.success} />
          <StatTile label="In Arbeit" value={stats.inProgressCount} accent={colors.cyan} />
          <StatTile label="Geplant" value={stats.upcomingCount} accent={colors.violet} />
        </View>
      ) : null}

      <SectionPanel title="Heutige Einsätze" subtitle="Chronologisch sortiert">
        {todayAssignments.length === 0 ? (
          <EmptyState
            title="Keine Einsätze heute"
            message="Für heute sind keine Einsätze geplant."
            actionLabel="Alle Einsätze anzeigen"
            onAction={() => router.push('/assist/assignments' as never)}
          />
        ) : (
          todayAssignments.map((assignment) => (
            <AssignmentListCard
              key={assignment.id}
              assignment={assignment}
              onPress={() => router.push(`/assist/assignments/${assignment.id}` as never)}
            />
          ))
        )}
      </SectionPanel>

      <SectionPanel title="Schnellzugriff" subtitle="Häufige Aktionen">
        <View style={styles.quickGrid}>
          <ModuleTile
            icon="📋"
            title="Alle Einsätze"
            description="Suche, Filter und Status"
            accentColor={colors.amber}
            isActive
            onPress={() => router.push('/assist/assignments' as never)}
          />
          <ModuleTile
            icon="📅"
            title="Wochenübersicht"
            description="Kalender und Einsätze"
            accentColor={colors.violet}
            isActive
            onPress={() => router.push('/assist/calendar' as never)}
          />
        </View>
        {can('assist.assignments.manage') ? (
          <PremiumButton
            title="Einsätze verwalten"
            fullWidth
            onPress={() => router.push('/assist/assignments' as never)}
          />
        ) : (
          <Text style={styles.readOnlyHint}>
            Lesemodus — Statusänderungen sind für {roleLabel ?? 'Ihre Rolle'} nicht freigegeben.
          </Text>
        )}
      </SectionPanel>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  statsGrid: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: spacing.sm,
    marginBottom: spacing.md,
  },
  statTile: {
    width: '47%',
    flexGrow: 1,
  },
  statValue: {
    ...typography.h2,
    marginBottom: 4,
  },
  statLabel: {
    ...typography.caption,
  },
  quickGrid: {
    gap: spacing.md,
    marginBottom: spacing.md,
  },
  readOnlyHint: {
    ...typography.caption,
    color: colors.textMuted,
  },
});
