import { FlatList, RefreshControl, StyleSheet, Text, View } from 'react-native';
import { useRouter } from 'expo-router';
import { ClientListCard } from '@/components/office';
import { ScreenShell } from '@/components/layout';
import {
  EmptyState,
  ErrorState,
  FilterChipGroup,
  LoadingState,
  PremiumButton,
  PremiumInput,
  SuccessState,
} from '@/components/ui';
import { useClientList } from '@/hooks/useClientList';
import { usePermissions } from '@/hooks/usePermissions';
import { colors, spacing, typography } from '@/theme';

export function ClientsListScreen({
  onClientPress,
  embedded = false,
}: {
  onClientPress?: (id: string) => void;
  embedded?: boolean;
} = {}) {
  const router = useRouter();
  const { can, isReadOnly, roleLabel } = usePermissions();
  const canCreate = can('office.clients.create');
  const {
    items,
    totalCount,
    filteredCount,
    loading,
    error,
    refreshing,
    showSuccess,
    search,
    setSearch,
    statusFilter,
    setStatusFilter,
    sortKey,
    setSortKey,
    sortOptions,
    statusFilters,
    hasMore,
    loadMore,
    refresh,
    resetFilters,
    hasActiveFilters,
    isEmpty,
    isFilterEmpty,
  } = useClientList();

  const header = (
    <View style={styles.toolbar}>
      {showSuccess ? (
        <SuccessState message="Liste erfolgreich aktualisiert." />
      ) : null}

      <PremiumInput
        label="Suche"
        placeholder="Name oder Ort suchen…"
        value={search}
        onChangeText={setSearch}
        autoCapitalize="words"
        autoCorrect={false}
        hint={`${filteredCount} von ${totalCount} Klient:innen`}
      />

      <Text style={styles.filterLabel}>Status</Text>
      <FilterChipGroup
        options={statusFilters}
        value={statusFilter}
        onChange={setStatusFilter}
      />

      <Text style={styles.filterLabel}>Sortierung</Text>
      <FilterChipGroup
        options={sortOptions}
        value={sortKey}
        onChange={setSortKey}
      />
    </View>
  );

  if (loading && items.length === 0) {
    return (
      <ScreenShell
        title="Klient:innen"
        subtitle="Wird geladen…"
        rightSlot={
          canCreate ? <PremiumButton title="+ Neu" size="sm" disabled /> : null
        }
      >
        <LoadingState message="Klient:innen werden geladen…" />
      </ScreenShell>
    );
  }

  if (error && items.length === 0 && totalCount === 0) {
    return (
      <ScreenShell title="Klient:innen" subtitle="Fehler">
        <ErrorState message={error} onRetry={refresh} />
      </ScreenShell>
    );
  }

  return (
    <ScreenShell
      title="Klient:innen"
      subtitle={`${filteredCount} Einträge${isReadOnly ? ' · Lesemodus' : ''}`}
      showBack={embedded ? false : undefined}
      rightSlot={
        canCreate ? (
          <PremiumButton
            title="+ Neu"
            size="sm"
            onPress={() => router.push('/office/clients/create' as never)}
          />
        ) : null
      }
      scroll={false}
    >
      <FlatList
        style={styles.flatList}
        data={items}
        keyExtractor={(item) => item.id}
        ListHeaderComponent={header}
        ListEmptyComponent={
          isEmpty ? (
            <EmptyState
              title="Noch keine Klient:innen"
              message={
                canCreate
                  ? 'Legen Sie die erste Klient:in an, um mit der Verwaltung zu beginnen.'
                  : `Noch keine Klient:innen vorhanden. Anlegen ist für ${roleLabel ?? 'Ihre Rolle'} nicht freigegeben.`
              }
              actionLabel={canCreate ? 'Klient:in anlegen' : undefined}
              onAction={canCreate ? () => router.push('/office/clients/create' as never) : undefined}
            />
          ) : isFilterEmpty ? (
            <EmptyState
              title="Keine Treffer"
              message="Für Ihre Suche oder Filter wurden keine Klient:innen gefunden."
              actionLabel="Filter zurücksetzen"
              onAction={resetFilters}
            />
          ) : null
        }
        ListFooterComponent={
          hasMore ? (
            <PremiumButton
              title="Weitere laden"
              variant="secondary"
              fullWidth
              onPress={loadMore}
              style={styles.loadMore}
            />
          ) : filteredCount > 0 ? (
            <Text style={styles.footer}>
              {filteredCount} Klient:innen angezeigt
              {hasActiveFilters ? ' (gefiltert)' : ''}
            </Text>
          ) : null
        }
        renderItem={({ item }) => (
          <ClientListCard
            client={item}
            onPress={() => {
              if (onClientPress) {
                onClientPress(item.id);
                return;
              }
              router.push(`/office/clients/${item.id}` as never);
            }}
          />
        )}
        contentContainerStyle={styles.list}
        showsVerticalScrollIndicator={false}
        refreshControl={
          <RefreshControl
            refreshing={refreshing}
            onRefresh={refresh}
            tintColor={colors.primary}
          />
        }
      />
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  flatList: {
    flex: 1,
  },
  toolbar: {
    gap: spacing.sm,
    marginBottom: spacing.md,
  },
  filterLabel: {
    ...typography.label,
    marginTop: spacing.xs,
  },
  list: {
    paddingBottom: spacing.xxl,
  },
  loadMore: {
    marginTop: spacing.sm,
    marginBottom: spacing.md,
  },
  footer: {
    ...typography.caption,
    textAlign: 'center',
    marginVertical: spacing.md,
  },
});
