import { RefreshControl, ScrollView, StyleSheet, Text, View } from 'react-native';
import { DetailInfoRow } from '@/components/detail';
import { LockedActionBanner } from '@/components/permissions';
import { ScreenShell } from '@/components/layout';
import {
  EmptyState,
  ErrorState,
  LoadingState,
  PremiumBadge,
  PremiumCard,
  PremiumKpiCard,
  SectionPanel,
} from '@/components/ui';
import { useClientPortalProfile } from '@/hooks/useClientPortalProfile';
import { usePermissions } from '@/hooks/usePermissions';
import { WORKFLOW_STATUS_LABELS } from '@/types/workflow/status';
import { colors, spacing, typography } from '@/theme';

function formatDateTime(iso: string): string {
  return new Date(iso).toLocaleString('de-DE', {
    weekday: 'short',
    day: '2-digit',
    month: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
  });
}

function formatDate(iso: string): string {
  return new Date(iso).toLocaleDateString('de-DE', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  });
}

export function ClientPortalProfileScreen() {
  const { can, check, roleLabel } = usePermissions();
  const canViewProfile = can('portal.client.profile.view');
  const canViewCarePlan = can('portal.client.careplan.view');

  const { profile, carePlans, loading, error, refresh } = useClientPortalProfile();

  if (!canViewProfile) {
    return (
      <ScreenShell title="Profil" subtitle={roleLabel ?? 'Portal'} showBack={false}>
        <LockedActionBanner
          message={check('portal.client.profile.view').reason ?? 'Keine Berechtigung.'}
          roleLabel={roleLabel}
        />
      </ScreenShell>
    );
  }

  if (loading && !profile) {
    return (
      <ScreenShell title="Profil" subtitle="Wird geladen…" showBack={false}>
        <LoadingState message="Profil wird geladen…" />
      </ScreenShell>
    );
  }

  if (error && !profile) {
    return (
      <ScreenShell title="Profil" subtitle="Fehler" showBack={false}>
        <ErrorState title="Profil nicht verfügbar" message={error} onRetry={refresh} />
      </ScreenShell>
    );
  }

  if (!profile) return null;

  return (
    <ScreenShell title="Profil" subtitle={profile.displayName} showBack={false}>
      <ScrollView
        showsVerticalScrollIndicator={false}
        refreshControl={
          <RefreshControl refreshing={loading} onRefresh={refresh} tintColor={colors.primary} />
        }
        contentContainerStyle={styles.scroll}
      >
        <PremiumCard accentColor={colors.primary}>
          <Text style={styles.name}>{profile.displayName}</Text>
          {profile.careLevel ? (
            <DetailInfoRow label="Pflegegrad" value={profile.careLevel} />
          ) : null}
          {profile.city ? (
            <DetailInfoRow
              label="Wohnort"
              value={`${profile.zip ?? ''} ${profile.city}`.trim()}
            />
          ) : null}
          {profile.primaryContactPhone ? (
            <DetailInfoRow label="Telefon" value={profile.primaryContactPhone} />
          ) : null}
          {profile.emergencyContact ? (
            <DetailInfoRow label="Notfallkontakt" value={profile.emergencyContact} />
          ) : null}
        </PremiumCard>

        <View style={styles.kpiRow}>
          <PremiumKpiCard
            label="Offene Rechnungen"
            value={profile.openInvoices}
            subValue="Portal"
          />
          <PremiumKpiCard
            label="Dokumente"
            value={profile.sharedDocuments}
            subValue="Freigegeben"
          />
        </View>

        {profile.nextAppointmentTitle && profile.nextAppointmentAt ? (
          <PremiumCard accentColor={colors.cyan}>
            <Text style={styles.nextLabel}>Nächster Termin</Text>
            <Text style={styles.nextTitle}>{profile.nextAppointmentTitle}</Text>
            <Text style={styles.nextMeta}>{formatDateTime(profile.nextAppointmentAt)}</Text>
          </PremiumCard>
        ) : null}

        {canViewCarePlan ? (
          <SectionPanel title="Pflegepläne">
            {carePlans.length === 0 ? (
              <EmptyState
                title="Keine Pflegepläne"
                message="Aktuell sind keine Pflegepläne für Sie freigegeben."
              />
            ) : (
              carePlans.map((plan) => (
                <PremiumCard key={plan.id} style={styles.planCard}>
                  <Text style={styles.planTitle}>{plan.title}</Text>
                  <Text style={styles.planMeta}>
                    {plan.validUntil
                      ? `Gültig bis ${formatDate(plan.validUntil)} · `
                      : ''}
                    {plan.taskCount} Maßnahmen
                  </Text>
                  <Text style={styles.planSummary}>{plan.summary}</Text>
                  <PremiumBadge
                    label={WORKFLOW_STATUS_LABELS[plan.status]}
                    variant="green"
                  />
                </PremiumCard>
              ))
            )}
          </SectionPanel>
        ) : (
          <LockedActionBanner
            message={check('portal.client.careplan.view').reason ?? 'Keine Berechtigung.'}
            roleLabel={roleLabel}
          />
        )}
      </ScrollView>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  scroll: {
    gap: spacing.md,
    paddingBottom: spacing.xxl,
  },
  name: {
    ...typography.h3,
    marginBottom: spacing.sm,
  },
  kpiRow: {
    flexDirection: 'row',
    gap: spacing.sm,
  },
  nextLabel: {
    ...typography.caption,
    color: colors.textSecondary,
  },
  nextTitle: {
    ...typography.bodyStrong,
    marginTop: spacing.xs,
  },
  nextMeta: {
    ...typography.caption,
    color: colors.textSecondary,
    marginTop: 2,
  },
  planCard: {
    marginBottom: spacing.sm,
  },
  planTitle: {
    ...typography.bodyStrong,
    marginBottom: spacing.xs,
  },
  planMeta: {
    ...typography.caption,
    color: colors.textSecondary,
    marginBottom: spacing.xs,
  },
  planSummary: {
    ...typography.body,
    color: colors.textSecondary,
    marginBottom: spacing.sm,
  },
});
