import { StyleSheet, Text, View } from 'react-native';
import { useRouter } from 'expo-router';
import { CarePlanListCard } from '@/components/pflege';
import { ScreenShell } from '@/components/layout';
import {
  EmptyState,
  ErrorState,
  LoadingState,
  ModuleTile,
  PremiumCard,
  SectionPanel,
  SuccessState,
} from '@/components/ui';
import { usePflegeDashboard } from '@/hooks/usePflegeDashboard';
import { usePermissions } from '@/hooks/usePermissions';
import { wp378A11y } from '@/lib/a11y/wp378-pflege';
import { colors, spacing, typography } from '@/theme';

function StatTile({ label, value, accent }: { label: string; value: number; accent: string }) {
  return (
    <PremiumCard style={styles.statTile} accentColor={accent}>
      <Text style={styles.statValue}>{value}</Text>
      <Text style={styles.statLabel}>{label}</Text>
    </PremiumCard>
  );
}

export function PflegeIndexScreen() {
  const router = useRouter();
  const { can, roleLabel } = usePermissions();
  const {
    stats,
    activePlans,
    loading,
    error,
    showSuccess,
    refresh,
  } = usePflegeDashboard();

  if (loading && !stats) {
    return (
      <ScreenShell title="CareSuite+ Pflege" subtitle="Ambulante Pflege">
        <LoadingState message="Dashboard wird geladen…" />
      </ScreenShell>
    );
  }

  if (error && !stats) {
    return (
      <ScreenShell title="CareSuite+ Pflege" subtitle="Fehler">
        <ErrorState message={error} onRetry={refresh} />
      </ScreenShell>
    );
  }

  return (
    <ScreenShell
      title="CareSuite+ Pflege"
      subtitle={`Ambulante Pflege · ${roleLabel ?? 'Demo'}`}
      a11yMeta={wp378A11y}
    >
      {showSuccess ? <SuccessState message="Dashboard aktualisiert." /> : null}

      {stats ? (
        <View style={styles.statsGrid}>
          <StatTile label="Aktive Pläne" value={stats.activePlansCount} accent={colors.success} />
          <StatTile label="Fällige Vitalwerte" value={stats.dueVitalsCount} accent={colors.warning} />
          <StatTile label="Hinweise" value={stats.alertsCount} accent={colors.danger} />
          <StatTile label="Gesamt" value={stats.totalPlans} accent={colors.cyan} />
        </View>
      ) : null}

      <SectionPanel title="Aktive Pflegepläne" subtitle="Zuletzt aktualisiert">
        {activePlans.length === 0 ? (
          <EmptyState
            title="Keine aktiven Pläne"
            message="Derzeit sind keine aktiven Pflegepläne hinterlegt."
            actionLabel="Alle Pflegepläne anzeigen"
            onAction={() => router.push('/pflege/plans' as never)}
          />
        ) : (
          activePlans.slice(0, 4).map((plan) => (
            <CarePlanListCard
              key={plan.id}
              plan={plan}
              onPress={() => router.push(`/pflege/plans/${plan.id}` as never)}
            />
          ))
        )}
      </SectionPanel>

      <SectionPanel title="Schnellzugriff" subtitle="Häufige Aktionen">
        <View style={styles.quickGrid}>
          {can('pflege.plans.view') ? (
            <ModuleTile
              icon="📋"
              title="Pflegepläne"
              description="Suche, Filter und Status"
              accentColor={colors.success}
              isActive
              onPress={() => router.push('/pflege/plans' as never)}
            />
          ) : null}
          {can('pflege.vitals.view') ? (
            <ModuleTile
              icon="❤️"
              title="Vitalwerte"
              description="Messungen und Fälligkeiten"
              accentColor={colors.cyan}
              isActive
              onPress={() => router.push('/pflege/vitalwerte' as never)}
            />
          ) : null}
          <ModuleTile
            icon="📊"
            title="SIS-Assessments"
            description="Strukturierte Informationssammlung"
            accentColor={colors.violet}
            preparedOnly
            onPress={() => router.push('/pflege/sis' as never)}
          />
          <ModuleTile
            icon="📈"
            title="Auswertungen"
            description="KPIs und Kennzahlen"
            accentColor={colors.amber}
            preparedOnly
            onPress={() => router.push('/pflege/auswertungen' as never)}
          />
          <ModuleTile
            icon="⚙️"
            title="Einstellungen"
            description="Modul-Konfiguration"
            accentColor={colors.textMuted}
            preparedOnly
            onPress={() => router.push('/pflege/settings' as never)}
          />
        </View>
        {!can('pflege.plans.view') && !can('pflege.vitals.view') ? (
          <Text style={styles.readOnlyHint}>
            Lesemodus — Detailbereiche sind für {roleLabel ?? 'Ihre Rolle'} nicht freigegeben.
          </Text>
        ) : null}
      </SectionPanel>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  statsGrid: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: spacing.sm,
    marginBottom: spacing.md,
  },
  statTile: {
    width: '47%',
    flexGrow: 1,
  },
  statValue: {
    ...typography.h2,
    marginBottom: 4,
  },
  statLabel: {
    ...typography.caption,
  },
  quickGrid: {
    gap: spacing.md,
    marginBottom: spacing.md,
  },
  readOnlyHint: {
    ...typography.caption,
    color: colors.textMuted,
  },
});
