import { RefreshControl, ScrollView, StyleSheet, Text, View } from 'react-native';
import { DetailInfoRow } from '@/components/detail';
import { LockedActionBanner } from '@/components/permissions';
import { ScreenShell } from '@/components/layout';
import {
  EmptyState,
  ErrorState,
  LoadingState,
  PremiumBadge,
  PremiumCard,
  PremiumKpiCard,
  SectionPanel,
} from '@/components/ui';
import { useEmployeePortalProfile } from '@/hooks/useEmployeePortalProfile';
import { usePermissions } from '@/hooks/usePermissions';
import { WORKFLOW_STATUS_LABELS } from '@/types/workflow/status';
import { colors, spacing, typography } from '@/theme';

export function EmployeeProfileScreen() {
  const { can, check, roleLabel } = usePermissions();
  const canViewProfile = can('portal.employee.profile.view');
  const canViewTimesheet = can('portal.employee.timesheet.view');

  const { profile, timesheet, loading, error, refresh } = useEmployeePortalProfile();

  if (!canViewProfile) {
    return (
      <ScreenShell title="Profil" subtitle={roleLabel ?? 'Portal'} showBack={false}>
        <LockedActionBanner
          message={check('portal.employee.profile.view').reason ?? 'Keine Berechtigung.'}
          roleLabel={roleLabel}
        />
      </ScreenShell>
    );
  }

  if (loading && !profile) {
    return (
      <ScreenShell title="Profil" subtitle="Wird geladen…" showBack={false}>
        <LoadingState message="Profil wird geladen…" />
      </ScreenShell>
    );
  }

  if (error && !profile) {
    return (
      <ScreenShell title="Profil" subtitle="Fehler" showBack={false}>
        <ErrorState title="Profil nicht verfügbar" message={error} onRetry={refresh} />
      </ScreenShell>
    );
  }

  if (!profile) return null;

  return (
    <ScreenShell
      title="Profil"
      subtitle={profile.displayName}
      showBack={false}
    >
      <ScrollView
        showsVerticalScrollIndicator={false}
        refreshControl={
          <RefreshControl refreshing={loading} onRefresh={refresh} tintColor={colors.primary} />
        }
        contentContainerStyle={styles.scroll}
      >
        <PremiumCard accentColor={colors.cyan}>
          <View style={styles.headerRow}>
            <Text style={styles.name}>{profile.displayName}</Text>
            <PremiumBadge
              label={WORKFLOW_STATUS_LABELS[profile.status]}
              variant={profile.status === 'aktiv' ? 'green' : 'orange'}
            />
          </View>
          {profile.jobTitle ? <DetailInfoRow label="Funktion" value={profile.jobTitle} /> : null}
          <DetailInfoRow label="Team" value={profile.teamName} />
          {profile.email ? <DetailInfoRow label="E-Mail" value={profile.email} /> : null}
          {profile.phone ? <DetailInfoRow label="Telefon" value={profile.phone} /> : null}
        </PremiumCard>

        <View style={styles.kpiRow}>
          <PremiumKpiCard
            label="Soll (Woche)"
            value={`${profile.weeklyHoursTarget} h`}
            subValue="Arbeitszeit"
          />
          <PremiumKpiCard
            label="Ist (Woche)"
            value={`${profile.weeklyHoursLogged} h`}
            subValue="Erfasst"
          />
        </View>

        <View style={styles.kpiRow}>
          <PremiumKpiCard
            label="Einsätze"
            value={profile.upcomingShifts}
            subValue="Anstehend"
          />
          <PremiumKpiCard
            label="Anfragen"
            value={profile.openRequests}
            subValue="Offen"
          />
        </View>

        {canViewTimesheet ? (
          <SectionPanel title="Zeiterfassung (letzte Einsätze)">
            {timesheet.length === 0 ? (
              <EmptyState
                title="Keine Einträge"
                message="Für diese Woche sind noch keine Zeiten erfasst."
              />
            ) : (
              timesheet.map((entry) => (
                <PremiumCard key={entry.id} style={styles.timesheetCard}>
                  <Text style={styles.entryTitle}>{entry.assignmentTitle}</Text>
                  <Text style={styles.entryMeta}>
                    {entry.date} · {entry.startTime}–{entry.endTime} ({entry.durationMinutes} Min.)
                  </Text>
                  <Text style={styles.entryMeta}>Klient:in: {entry.clientName}</Text>
                  <PremiumBadge
                    label={WORKFLOW_STATUS_LABELS[entry.status]}
                    variant="muted"
                  />
                </PremiumCard>
              ))
            )}
          </SectionPanel>
        ) : (
          <LockedActionBanner
            message={check('portal.employee.timesheet.view').reason ?? 'Keine Berechtigung.'}
            roleLabel={roleLabel}
          />
        )}
      </ScrollView>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  scroll: {
    gap: spacing.md,
    paddingBottom: spacing.xxl,
  },
  headerRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'flex-start',
    gap: spacing.sm,
    marginBottom: spacing.sm,
  },
  name: {
    ...typography.h3,
    flex: 1,
  },
  kpiRow: {
    flexDirection: 'row',
    gap: spacing.sm,
  },
  timesheetCard: {
    marginBottom: spacing.sm,
  },
  entryTitle: {
    ...typography.bodyStrong,
    marginBottom: spacing.xs,
  },
  entryMeta: {
    ...typography.caption,
    color: colors.textSecondary,
    marginBottom: 2,
  },
});
