import { FlatList, RefreshControl, StyleSheet, Text, View } from 'react-native';
import { PreparedModeBanner } from '@/components/modules/PreparedModeBanner';
import { ScreenShell } from '@/components/layout';
import { EmptyState, ErrorState, LoadingState, PremiumBadge, PremiumCard } from '@/components/ui';
import { useAsyncQuery } from '@/hooks/core/useAsyncQuery';
import { usePermissions } from '@/hooks/usePermissions';
import { useServiceTenantId } from '@/hooks/useTenantId';
import { useAuth } from '@/lib/auth/context';
import { fetchSisAssessments } from '@/lib/pflege/moduleExtensionService';
import type { SisAssessment } from '@/types/modules/pflege';
import { colors, spacing, typography } from '@/theme';

function SisCard({ item }: { item: SisAssessment }) {
  const reviewLabel = item.nextReviewAt
    ? new Date(item.nextReviewAt).toLocaleDateString('de-DE')
    : '—';

  return (
    <PremiumCard style={styles.card} accentColor={colors.violet}>
      <View style={styles.cardHeader}>
        <Text style={styles.title}>{item.clientName}</Text>
        <PremiumBadge label={`${item.overallScore} Pkt.`} variant="cyan" />
      </View>
      <Text style={styles.meta}>
        Bewertet: {new Date(item.assessedAt).toLocaleDateString('de-DE')} · {item.assessorName}
      </Text>
      <Text style={styles.meta}>Nächste Prüfung: {reviewLabel}</Text>
      <PremiumBadge label={item.status} variant="muted" />
    </PremiumCard>
  );
}

export function SisOverviewScreen() {
  const { profile } = useAuth();
  const tenantId = useServiceTenantId();
  const { roleLabel } = usePermissions();

  const query = useAsyncQuery(
    () => {
      if (!tenantId) return Promise.resolve({ ok: false as const, error: 'Kein Mandant.' });
      return fetchSisAssessments(tenantId, profile?.roleKey);
    },
    [tenantId, profile?.roleKey],
    { enabled: !!tenantId },
  );

  const items = query.data ?? [];

  if (query.loading && items.length === 0) {
    return (
      <ScreenShell title="SIS-Übersicht" subtitle="Wird geladen…">
        <LoadingState message="SIS-Assessments werden geladen…" />
      </ScreenShell>
    );
  }

  if (query.error && items.length === 0) {
    return (
      <ScreenShell title="SIS-Übersicht" subtitle="Fehler">
        <ErrorState message={query.error} onRetry={query.refresh} />
      </ScreenShell>
    );
  }

  return (
    <ScreenShell title="SIS-Übersicht" subtitle={`Strukturierte Information · ${roleLabel ?? 'Demo'}`} scroll={false}>
      <FlatList
        data={items}
        keyExtractor={(item) => item.id}
        ListHeaderComponent={
          <View style={styles.header}>
            <PreparedModeBanner hint="SIS-Detail und Neu-Anlegen folgen — Übersicht mit Demo-Assessments." />
            <Text style={styles.count}>{items.length} Assessments</Text>
          </View>
        }
        ListEmptyComponent={
          <EmptyState
            title="Keine SIS-Assessments"
            message="Für diesen Mandanten sind noch keine strukturierten Assessments hinterlegt."
          />
        }
        renderItem={({ item }) => <SisCard item={item} />}
        contentContainerStyle={styles.list}
        refreshControl={
          <RefreshControl refreshing={query.refreshing} onRefresh={query.refresh} tintColor={colors.primary} />
        }
      />
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  header: { marginBottom: spacing.sm },
  count: { ...typography.caption, color: colors.textMuted, marginBottom: spacing.sm },
  list: { paddingBottom: spacing.xxl },
  card: { marginBottom: spacing.sm },
  cardHeader: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: spacing.xs },
  title: { ...typography.h3, flex: 1, marginRight: spacing.sm },
  meta: { ...typography.caption, color: colors.textMuted, marginBottom: 4 },
});
