import { FlatList, RefreshControl, StyleSheet, Text } from 'react-native';
import { VitalReadingListCard } from '@/components/pflege';
import { ScreenShell } from '@/components/layout';
import { EmptyState, ErrorState, LoadingState } from '@/components/ui';
import { fetchVitalReadings } from '@/lib/pflege';
import { useAuth } from '@/lib/auth/context';
import { usePermissions } from '@/hooks/usePermissions';
import { useServiceTenantId } from '@/hooks/useTenantId';
import { useAsyncQuery } from '@/hooks/core';
import { colors, spacing, typography } from '@/theme';

export function VitalReadingsListScreen() {
  const { profile } = useAuth();
  const { roleLabel } = usePermissions();
  const tenantId = useServiceTenantId();

  const query = useAsyncQuery(
    () => {
      if (!tenantId) return Promise.resolve({ ok: false as const, error: 'Kein Mandant am Profil hinterlegt.' });
      return fetchVitalReadings(tenantId, profile?.roleKey);
    },
    [tenantId, profile?.roleKey],
    { enabled: !!tenantId },
  );

  const items = query.data ?? [];

  if (query.loading && items.length === 0) {
    return (
      <ScreenShell title="Vitalwerte" subtitle="Wird geladen…">
        <LoadingState message="Vitalwerte werden geladen…" />
      </ScreenShell>
    );
  }

  if (query.error && items.length === 0) {
    return (
      <ScreenShell title="Vitalwerte" subtitle="Fehler">
        <ErrorState message={query.error} onRetry={query.refresh} />
      </ScreenShell>
    );
  }

  return (
    <ScreenShell
      title="Vitalwerte"
      subtitle={`${items.length} Messungen · ${roleLabel ?? 'Demo'}`}
      scroll={false}
    >
      <FlatList
        style={styles.flatList}
        data={items}
        keyExtractor={(item) => item.id}
        ListEmptyComponent={
          <EmptyState
            title="Keine Vitalwerte"
            message="Es sind keine Vitalwert-Messungen hinterlegt."
          />
        }
        ListFooterComponent={
          items.length > 0 ? (
            <Text style={styles.footer}>{items.length} Messungen angezeigt</Text>
          ) : null
        }
        renderItem={({ item }) => <VitalReadingListCard reading={item} />}
        contentContainerStyle={styles.list}
        showsVerticalScrollIndicator={false}
        refreshControl={
          <RefreshControl
            refreshing={query.refreshing}
            onRefresh={query.refresh}
            tintColor={colors.primary}
          />
        }
      />
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  flatList: { flex: 1 },
  list: { paddingBottom: spacing.xxl },
  footer: { ...typography.caption, textAlign: 'center', marginVertical: spacing.md },
});
