import { useState } from 'react';
import { MasterDetailLayout } from '@/components/layout';
import { usePlatformLayout } from '@/hooks/platform/usePlatformLayout';
import { ClientDetailScreen } from './ClientDetailScreen';
import { ClientsListScreen } from './ClientsListScreen';

export function ClientsAdaptiveScreen() {
  const { useMasterDetail } = usePlatformLayout();
  const [selectedId, setSelectedId] = useState<string | null>(null);

  if (!useMasterDetail) {
    return <ClientsListScreen />;
  }

  return (
    <MasterDetailLayout
      master={<ClientsListScreen embedded onClientPress={setSelectedId} />}
      detail={
        selectedId ? (
          <ClientDetailScreen clientId={selectedId} embedded />
        ) : (
          <></>
        )
      }
      showDetail={!!selectedId}
    />
  );
}
