import { FlatList, RefreshControl, StyleSheet, Text, View } from 'react-native';
import { useRouter } from 'expo-router';
import { EmployeeListCard } from '@/components/office';
import { LockedActionBanner } from '@/components/permissions';
import { ScreenShell } from '@/components/layout';
import {
  EmptyState,
  ErrorState,
  FilterChipGroup,
  LoadingState,
  PremiumButton,
  PremiumInput,
  SuccessState,
} from '@/components/ui';
import { useEmployeeList } from '@/hooks/useEmployeeList';
import { usePermissions } from '@/hooks/usePermissions';
import { colors, spacing, typography } from '@/theme';

export function EmployeesListScreen() {
  const router = useRouter();
  const { can, check, roleLabel } = usePermissions();
  const canView = can('office.employees.view');
  const canCreate = can('office.employees.create');
  const {
    items,
    totalCount,
    filteredCount,
    loading,
    error,
    refreshing,
    showSuccess,
    search,
    setSearch,
    statusFilter,
    setStatusFilter,
    sortKey,
    setSortKey,
    sortOptions,
    statusFilters,
    hasMore,
    loadMore,
    refresh,
    resetFilters,
    hasActiveFilters,
    isEmpty,
    isFilterEmpty,
  } = useEmployeeList();

  if (!canView) {
    return (
      <ScreenShell title="Mitarbeitende" subtitle="Kein Zugriff">
        <LockedActionBanner
          message={check('office.employees.view').reason ?? 'Keine Berechtigung.'}
          roleLabel={roleLabel}
        />
      </ScreenShell>
    );
  }

  const header = (
    <View style={styles.toolbar}>
      {showSuccess ? <SuccessState message="Liste erfolgreich aktualisiert." /> : null}
      <PremiumInput
        label="Suche"
        placeholder="Name, Rolle oder E-Mail…"
        value={search}
        onChangeText={setSearch}
        hint={`${filteredCount} von ${totalCount} Mitarbeitende`}
      />
      <Text style={styles.filterLabel}>Status</Text>
      <FilterChipGroup options={statusFilters} value={statusFilter} onChange={setStatusFilter} />
      <Text style={styles.filterLabel}>Sortierung</Text>
      <FilterChipGroup options={sortOptions} value={sortKey} onChange={setSortKey} />
      {canCreate ? (
        <PremiumButton
          title="Mitarbeitende anlegen"
          fullWidth
          onPress={() => router.push('/office/employees/create' as never)}
        />
      ) : null}
    </View>
  );

  if (loading && items.length === 0) {
    return (
      <ScreenShell title="Mitarbeitende" subtitle="Wird geladen…">
        <LoadingState message="Team wird geladen…" />
      </ScreenShell>
    );
  }

  if (error && items.length === 0 && totalCount === 0) {
    return (
      <ScreenShell title="Mitarbeitende" subtitle="Fehler">
        <ErrorState message={error} onRetry={refresh} />
      </ScreenShell>
    );
  }

  return (
    <ScreenShell
      title="Mitarbeitende"
      subtitle={`${filteredCount} Einträge`}
      scroll={false}
    >
      <FlatList
        style={styles.flatList}
        data={items}
        keyExtractor={(item) => item.id}
        ListHeaderComponent={header}
        ListEmptyComponent={
          isEmpty ? (
            <EmptyState
              title="Noch keine Mitarbeitenden"
              message="Legen Sie Teammitglieder an, sobald die Anlage-Funktion freigeschaltet ist."
            />
          ) : isFilterEmpty ? (
            <EmptyState
              title="Keine Treffer"
              message="Für Ihre Suche oder Filter wurden keine Mitarbeitenden gefunden."
              actionLabel="Filter zurücksetzen"
              onAction={resetFilters}
            />
          ) : null
        }
        ListFooterComponent={
          hasMore ? (
            <Text style={styles.footer} onPress={loadMore}>
              Weitere laden ({filteredCount - items.length} verbleibend)
            </Text>
          ) : filteredCount > 0 ? (
            <Text style={styles.footer}>
              {filteredCount} Mitarbeitende angezeigt
              {hasActiveFilters ? ' (gefiltert)' : ''}
            </Text>
          ) : null
        }
        renderItem={({ item }) => (
          <EmployeeListCard
            employee={item}
            onPress={() => router.push(`/office/employees/${item.id}` as never)}
          />
        )}
        contentContainerStyle={styles.list}
        refreshControl={
          <RefreshControl refreshing={refreshing} onRefresh={refresh} tintColor={colors.primary} />
        }
      />
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  flatList: { flex: 1 },
  toolbar: { gap: spacing.sm, marginBottom: spacing.md },
  filterLabel: { ...typography.label, marginTop: spacing.xs },
  list: { paddingBottom: spacing.xxl, gap: spacing.sm },
  footer: { ...typography.caption, textAlign: 'center', marginVertical: spacing.md, color: colors.cyan },
});
