import { StyleSheet, Text, View } from 'react-native';
import { useRouter } from 'expo-router';
import { InactiveModuleBanner, ResidentListCard } from '@/components/stationaer';
import { ScreenShell } from '@/components/layout';
import {
  EmptyState,
  ErrorState,
  LoadingState,
  ModuleTile,
  PremiumCard,
  SectionPanel,
  SuccessState,
} from '@/components/ui';
import { useStationaerDashboard } from '@/hooks/useStationaerDashboard';
import { usePermissions } from '@/hooks/usePermissions';
import { wp398A11y } from '@/lib/a11y/wp398-stationaer';
import { colors, spacing, typography } from '@/theme';

function StatTile({ label, value, accent }: { label: string; value: number | string; accent: string }) {
  return (
    <PremiumCard style={styles.statTile} accentColor={accent}>
      <Text style={styles.statValue}>{value}</Text>
      <Text style={styles.statLabel}>{label}</Text>
    </PremiumCard>
  );
}

export function StationaerIndexScreen() {
  const router = useRouter();
  const { can, roleLabel } = usePermissions();
  const { stats, activeResidents, loading, error, showSuccess, refresh } = useStationaerDashboard();

  if (loading && !stats) {
    return (
      <ScreenShell title="CareSuite+ Stationär" subtitle="Pflegeheim">
        <LoadingState message="Dashboard wird geladen…" />
      </ScreenShell>
    );
  }

  if (error && !stats) {
    return (
      <ScreenShell title="CareSuite+ Stationär" subtitle="Fehler">
        <ErrorState message={error} onRetry={refresh} />
      </ScreenShell>
    );
  }

  return (
    <ScreenShell title="CareSuite+ Stationär" subtitle={`Pflegeheim · ${roleLabel ?? 'Demo'}`} a11yMeta={wp398A11y}>
      <InactiveModuleBanner productKey="stationaer" />
      {showSuccess ? <SuccessState message="Dashboard aktualisiert." /> : null}

      {stats ? (
        <View style={styles.statsGrid}>
          <StatTile label="Bewohner:innen" value={stats.totalResidents} accent={colors.violet} />
          <StatTile label="Aktiv" value={stats.activeCount} accent={colors.success} />
          <StatTile label="Neuaufnahmen" value={stats.newAdmissionsCount} accent={colors.cyan} />
          <StatTile label="Belegung" value={`${stats.occupancyPercent} %`} accent={colors.amber} />
        </View>
      ) : null}

      <SectionPanel title="Aktive Bewohner:innen" subtitle="Alphabetisch sortiert">
        {activeResidents.length === 0 ? (
          <EmptyState
            title="Keine aktiven Bewohner:innen"
            message="Derzeit sind keine aktiven Bewohner:innen hinterlegt."
            actionLabel="Alle Bewohner:innen anzeigen"
            onAction={() => router.push('/stationaer/bewohner' as never)}
          />
        ) : (
          activeResidents.map((resident) => (
            <ResidentListCard
              key={resident.id}
              resident={resident}
              onPress={() => router.push(`/stationaer/bewohner/${resident.id}` as never)}
            />
          ))
        )}
      </SectionPanel>

      <SectionPanel title="Schnellzugriff" subtitle="Häufige Aktionen">
        <View style={styles.quickGrid}>
          <ModuleTile
            icon="🏥"
            title="Alle Bewohner:innen"
            description="Suche, Filter und Zimmer"
            accentColor={colors.violet}
            isActive={false}
            onPress={() => router.push('/stationaer/bewohner' as never)}
          />
          <ModuleTile
            icon="🛏️"
            title="Wohnbereiche"
            description="Zimmer und Belegung"
            accentColor={colors.cyan}
            isActive
            onPress={() => router.push('/stationaer/wohnbereiche' as never)}
          />
          <ModuleTile
            icon="📝"
            title="Übergabebericht"
            description="Schichtübergabe dokumentieren"
            accentColor={colors.amber}
            preparedOnly
            onPress={() => router.push('/stationaer/uebergabebericht' as never)}
          />
          <ModuleTile
            icon="📈"
            title="Auswertungen"
            description="Belegung und Kennzahlen"
            accentColor={colors.success}
            preparedOnly
            onPress={() => router.push('/stationaer/auswertungen' as never)}
          />
          <ModuleTile
            icon="⚙️"
            title="Einstellungen"
            description="Modul-Konfiguration"
            accentColor={colors.textMuted}
            preparedOnly
            onPress={() => router.push('/stationaer/settings' as never)}
          />
        </View>
        {!can('stationaer.residents.view') ? (
          <Text style={styles.readOnlyHint}>
            Lesemodus — Bewohner:innen sind für {roleLabel ?? 'Ihre Rolle'} nicht sichtbar.
          </Text>
        ) : null}
      </SectionPanel>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  statsGrid: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: spacing.sm,
    marginBottom: spacing.md,
  },
  statTile: { width: '47%', flexGrow: 1 },
  statValue: { ...typography.h2, marginBottom: 4 },
  statLabel: { ...typography.caption },
  quickGrid: { gap: spacing.md, marginBottom: spacing.md },
  readOnlyHint: { ...typography.caption, color: colors.textMuted },
});
