import { Pressable, StyleSheet, Text, View } from 'react-native';
import { PremiumBadge, PremiumCard } from '@/components/ui';
import type { CounselingListItem } from '@/types/modules/beratung';
import { WORKFLOW_STATUS_LABELS } from '@/types/workflow/status';
import { colors, spacing, typography } from '@/theme';

type CounselingCaseListCardProps = {
  counselingCase: CounselingListItem;
  onPress?: () => void;
};

function statusVariant(status: CounselingListItem['status']) {
  switch (status) {
    case 'aktiv':
      return 'green' as const;
    case 'fehlerhaft':
    case 'gesperrt':
      return 'red' as const;
    case 'in_bearbeitung':
    case 'entwurf':
      return 'orange' as const;
    default:
      return 'muted' as const;
  }
}

function formatDate(iso: string): string {
  return new Date(iso).toLocaleDateString('de-DE', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  });
}

export function CounselingCaseListCard({ counselingCase, onPress }: CounselingCaseListCardProps) {
  const inner = (
    <>
      <View style={styles.header}>
        <Text style={styles.title}>{counselingCase.subject}</Text>
        <PremiumBadge
          label={WORKFLOW_STATUS_LABELS[counselingCase.status]}
          variant={statusVariant(counselingCase.status)}
          dot
        />
      </View>
      <Text style={styles.meta}>
        {counselingCase.clientName} · {counselingCase.counselorName}
      </Text>
      <Text style={styles.category}>{counselingCase.category}</Text>
      <Text style={styles.date}>
        Eröffnet {formatDate(counselingCase.openedAt)}
        {counselingCase.nextAppointmentAt
          ? ` · Nächster Termin ${formatDate(counselingCase.nextAppointmentAt)}`
          : ''}
      </Text>
    </>
  );

  if (!onPress) {
    return <PremiumCard style={styles.card}>{inner}</PremiumCard>;
  }

  return (
    <Pressable onPress={onPress}>
      <PremiumCard style={styles.card} accentColor={colors.cyan}>
        {inner}
      </PremiumCard>
    </Pressable>
  );
}

const styles = StyleSheet.create({
  card: { marginBottom: spacing.sm },
  header: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'flex-start',
    gap: spacing.sm,
    marginBottom: 4,
  },
  title: { ...typography.bodyStrong, flex: 1 },
  meta: { ...typography.caption, marginBottom: 4 },
  category: { ...typography.caption, color: colors.cyan, marginBottom: 4 },
  date: { ...typography.caption },
});
