import { ScrollView, StyleSheet, Text, View } from 'react-native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { DetailInfoRow } from '@/components/detail';
import { ScreenShell } from '@/components/layout';
import {
  ErrorState,
  LoadingState,
  PremiumBadge,
  PremiumButton,
  PremiumCard,
  SectionPanel,
} from '@/components/ui';
import { useBudgetDetail } from '@/hooks/useBudgetDetail';
import { usePermissions } from '@/hooks/usePermissions';
import { formatCurrency } from '@/lib/office';
import { WORKFLOW_STATUS_LABELS } from '@/types/workflow/status';
import { colors, spacing, typography } from '@/theme';

const PERIOD_LABELS = {
  monthly: 'Monatlich',
  quarterly: 'Quartal',
  yearly: 'Jährlich',
} as const;

export function BudgetDetailScreen() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const router = useRouter();
  const { can, roleLabel } = usePermissions();
  const { data: budget, loading, error, refresh, notFound } = useBudgetDetail(id);

  if (!can('office.budgets.view')) {
    return (
      <ScreenShell title="Budget" subtitle="Kein Zugriff">
        <ErrorState
          title="Zugriff verweigert"
          message={`Budgets sind für ${roleLabel ?? 'Ihre Rolle'} nicht freigegeben.`}
        />
      </ScreenShell>
    );
  }

  if (loading) {
    return (
      <ScreenShell title="Budget" subtitle="Wird geladen…">
        <LoadingState message="Budget wird geladen…" />
      </ScreenShell>
    );
  }

  if (notFound || error) {
    return (
      <ScreenShell title="Budget" subtitle="Fehler">
        <ErrorState message={error ?? 'Budget nicht gefunden.'} onRetry={refresh} />
        <PremiumButton title="Zurück" variant="secondary" onPress={() => router.back()} />
      </ScreenShell>
    );
  }

  if (!budget) return null;

  const remaining = budget.allocatedCents - budget.usedCents;

  return (
    <ScreenShell title={budget.label} subtitle={budget.clientName}>
      <ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={styles.scroll}>
        <PremiumCard accentColor={budget.usagePercent >= 85 ? colors.danger : colors.cyan}>
          <Text style={styles.usage}>{budget.usagePercent} % ausgeschöpft</Text>
          <Text style={styles.amount}>
            {formatCurrency(budget.usedCents, budget.currency)} /{' '}
            {formatCurrency(budget.allocatedCents, budget.currency)}
          </Text>
          <Text style={styles.remaining}>
            Verbleibend: {formatCurrency(Math.max(0, remaining), budget.currency)}
          </Text>
          <PremiumBadge label={WORKFLOW_STATUS_LABELS[budget.status]} variant="muted" dot />
        </PremiumCard>

        <SectionPanel title="Details">
          <DetailInfoRow label="Klient:in" value={budget.clientName} />
          <DetailInfoRow label="Zeitraum" value={PERIOD_LABELS[budget.period]} />
          {budget.notes ? <DetailInfoRow label="Hinweise" value={budget.notes} /> : null}
        </SectionPanel>

        {budget.linkedInvoiceIds.length > 0 ? (
          <SectionPanel title="Verknüpfte Rechnungen" subtitle="Demo-Verknüpfung über Klient:in">
            {budget.linkedInvoiceIds.map((invId) => (
              <PremiumButton
                key={invId}
                title={`Rechnung ${invId}`}
                variant="secondary"
                size="sm"
                onPress={() => router.push(`/office/invoices/${invId}` as never)}
                style={styles.invBtn}
              />
            ))}
          </SectionPanel>
        ) : null}

        <PremiumButton
          title="Zur Klient:in"
          variant="secondary"
          fullWidth
          onPress={() => router.push(`/office/clients/${budget.clientId}` as never)}
        />
      </ScrollView>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  scroll: { paddingBottom: spacing.xxl, gap: spacing.md },
  usage: { ...typography.caption, marginBottom: 4 },
  amount: { ...typography.h2, color: colors.cyan },
  remaining: { ...typography.body, marginTop: spacing.sm, marginBottom: spacing.sm },
  invBtn: { marginBottom: spacing.xs },
});
