import { StyleSheet, Text, View } from 'react-native';
import { useRouter } from 'expo-router';
import { ScreenShell } from '@/components/layout';
import { ModuleTile, PremiumButton, PremiumCard, SectionPanel } from '@/components/ui';
import { getAccessDashboardStats } from '@/lib/auth/accessManagementService';
import { DEMO_TENANT_ID } from '@/data/demo/tenant';
import { colors, spacing, typography } from '@/theme';

const QUICK_ACTIONS = [
  { title: 'Interne:n Benutzer:in anlegen', route: '/business/office/access/internal-users/new' },
  { title: 'Mitarbeiterzugang erstellen', route: '/business/office/access/employee-portal' },
  { title: 'Klient:innen-Code generieren', route: '/business/office/access/client-portal' },
  { title: 'Angehörigen-Code generieren', route: '/business/office/access/relative-portal' },
  { title: 'Rollen & Rechte verwalten', route: '/business/office/access/roles' },
  { title: 'Login-Protokoll anzeigen', route: '/business/office/access/login-audit' },
] as const;

export function AccessManagementDashboardScreen() {
  const router = useRouter();
  const stats = getAccessDashboardStats(DEMO_TENANT_ID);

  return (
    <ScreenShell title="Zugänge & Benutzer" subtitle="Office / Verwaltung" scroll>
      <View style={styles.kpis}>
        {[
          ['Interne Benutzer', stats.internalUsers],
          ['Mitarbeiterzugänge', stats.employeeAccounts],
          ['Aktive Portal-Codes', stats.activePortalCodes],
          ['Gesperrte Zugänge', stats.blockedAccesses],
          ['Offene Erst-Logins', stats.pendingFirstLogins],
          ['Letzte Logins', stats.recentLogins],
        ].map(([label, value]) => (
          <PremiumCard key={label as string} accentColor={colors.cyan}>
            <Text style={styles.kpiValue}>{value}</Text>
            <Text style={styles.kpiLabel}>{label}</Text>
          </PremiumCard>
        ))}
      </View>

      <SectionPanel title="Bereiche">
        <View style={styles.grid}>
          {[
            ['Interne Benutzer', '/business/office/access/internal-users'],
            ['Mitarbeitendenportal', '/business/office/access/employee-portal'],
            ['Klient:innenportal', '/business/office/access/client-portal'],
            ['Angehörigenportal', '/business/office/access/relative-portal'],
          ].map(([title, route]) => (
            <ModuleTile
              key={route}
              icon="🔐"
              title={title}
              description="Zugänge verwalten"
              accentColor={colors.orange}
              onPress={() => router.push(route as never)}
            />
          ))}
        </View>
      </SectionPanel>

      <SectionPanel title="Schnellaktionen">
        <View style={styles.actions}>
          {QUICK_ACTIONS.map((action) => (
            <PremiumButton
              key={action.route}
              title={action.title}
              variant="secondary"
              fullWidth
              onPress={() => router.push(action.route as never)}
            />
          ))}
        </View>
      </SectionPanel>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  kpis: { flexDirection: 'row', flexWrap: 'wrap', gap: spacing.sm },
  kpiValue: { ...typography.h2 },
  kpiLabel: { ...typography.caption, color: colors.textSecondary },
  grid: { gap: spacing.sm },
  actions: { gap: spacing.sm },
});
