import { StyleSheet, Text, View } from 'react-native';
import { PreparedModeBanner } from '@/components/modules/PreparedModeBanner';
import { ScreenShell } from '@/components/layout';
import { ErrorState, LoadingState, PremiumCard } from '@/components/ui';
import { useAsyncQuery } from '@/hooks/core/useAsyncQuery';
import { usePermissions } from '@/hooks/usePermissions';
import { useServiceTenantId } from '@/hooks/useTenantId';
import { useAuth } from '@/lib/auth/context';
import { fetchPflegeReportStats } from '@/lib/pflege/moduleExtensionService';
import { colors, spacing, typography } from '@/theme';

function KpiCard({ label, value, accent }: { label: string; value: number | string; accent: string }) {
  return (
    <PremiumCard style={styles.kpi} accentColor={accent}>
      <Text style={styles.kpiValue}>{value}</Text>
      <Text style={styles.kpiLabel}>{label}</Text>
    </PremiumCard>
  );
}

export function PflegeReportsScreen() {
  const { profile } = useAuth();
  const tenantId = useServiceTenantId();
  const { roleLabel } = usePermissions();

  const query = useAsyncQuery(
    () => {
      if (!tenantId) return Promise.resolve({ ok: false as const, error: 'Kein Mandant.' });
      return fetchPflegeReportStats(tenantId, profile?.roleKey);
    },
    [tenantId, profile?.roleKey],
    { enabled: !!tenantId },
  );

  if (query.loading && !query.data) {
    return (
      <ScreenShell title="Pflege-Auswertungen" subtitle="Wird geladen…">
        <LoadingState message="Kennzahlen werden geladen…" />
      </ScreenShell>
    );
  }

  if (query.error && !query.data) {
    return (
      <ScreenShell title="Pflege-Auswertungen" subtitle="Fehler">
        <ErrorState message={query.error} onRetry={query.refresh} />
      </ScreenShell>
    );
  }

  const stats = query.data!;

  return (
    <ScreenShell title="Pflege-Auswertungen" subtitle={`Kennzahlen · ${roleLabel ?? 'Demo'}`}>
      <PreparedModeBanner />
      <View style={styles.grid}>
        <KpiCard label="Aktive Pläne" value={stats.activePlans} accent={colors.success} />
        <KpiCard label="SIS fällig" value={stats.sisAssessmentsDue} accent={colors.warning} />
        <KpiCard label="Vitalwerte (Woche)" value={stats.vitalsDocumentedThisWeek} accent={colors.cyan} />
        <KpiCard label="Offene Wunden" value={stats.woundCasesOpen} accent={colors.danger} />
        <KpiCard label="MDK-bereit" value={stats.mdkReadyCount} accent={colors.violet} />
      </View>
      <Text style={styles.note}>
        Auswertungen basieren auf Demo-Daten. Export und MDK-Schnittstelle sind vorbereitet (P-READY).
      </Text>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  grid: { flexDirection: 'row', flexWrap: 'wrap', gap: spacing.sm, marginBottom: spacing.md },
  kpi: { width: '47%', flexGrow: 1 },
  kpiValue: { ...typography.h2, marginBottom: 4 },
  kpiLabel: { ...typography.caption },
  note: { ...typography.caption, color: colors.textMuted },
});
