import { StyleSheet, Text, View } from 'react-native';
import { useRouter } from 'expo-router';
import { LockedActionBanner } from '@/components/permissions';
import { PreparedTemplateBanner } from '@/components/templates';
import { ScreenShell } from '@/components/layout';
import {
  ErrorState,
  LoadingState,
  ModuleTile,
  PremiumButton,
  PremiumCard,
  PremiumKpiCard,
  SectionPanel,
} from '@/components/ui';
import { useAsyncQuery } from '@/hooks/core/useAsyncQuery';
import { usePermissions } from '@/hooks/usePermissions';
import { useServiceTenantId } from '@/hooks/useTenantId';
import { useAuth } from '@/lib/auth/context';
import { getTemplateDashboardStats } from '@/lib/templates';
import { colors, spacing, typography } from '@/theme';

const QUICK_ACTIONS = [
  { title: 'Neue Vorlage', route: '/business/templates/create', icon: '➕' },
  { title: 'Systemvorlagen', route: '/business/templates/system', icon: '🏛️' },
  { title: 'Kataloge', route: '/business/templates/catalogs', icon: '📚' },
  { title: 'Textbausteine', route: '/business/templates/text-blocks', icon: '📝' },
  { title: 'Dokumentvorlagen', route: '/business/templates/document-templates', icon: '📄' },
  { title: 'Nachrichten', route: '/business/templates/message-templates', icon: '💬' },
  { title: 'Pflege', route: '/business/templates/care-templates', icon: '❤️' },
  { title: 'Beratung', route: '/business/templates/counseling-templates', icon: '📋' },
  { title: 'Akademie', route: '/business/templates/academy-templates', icon: '🎓' },
];

export function TemplateCenterScreen() {
  const router = useRouter();
  const { profile } = useAuth();
  const tenantId = useServiceTenantId();
  const { can, check, roleLabel } = usePermissions();

  const query = useAsyncQuery(
    () => {
      if (!tenantId) return Promise.resolve({ ok: false as const, error: 'Kein Mandant.' });
      return getTemplateDashboardStats(tenantId, profile?.roleKey);
    },
    [tenantId, profile?.roleKey],
    { enabled: !!tenantId },
  );

  if (!can('office.catalogs.view')) {
    return (
      <ScreenShell title="Template Center" subtitle={roleLabel ?? 'Vorlagen'} showBack={false}>
        <LockedActionBanner
          message={check('office.catalogs.view').reason ?? 'Keine Berechtigung.'}
          roleLabel={roleLabel}
        />
      </ScreenShell>
    );
  }

  if (query.loading && !query.data) {
    return (
      <ScreenShell title="Template Center" subtitle="Wird geladen…" showBack={false}>
        <LoadingState message="KPIs werden geladen…" />
      </ScreenShell>
    );
  }

  if (query.error && !query.data) {
    return (
      <ScreenShell title="Template Center" subtitle="Fehler" showBack={false}>
        <ErrorState message={query.error} onRetry={query.refresh} />
      </ScreenShell>
    );
  }

  const stats = query.data!;

  return (
    <ScreenShell title="Template Center" subtitle="Zentrale Vorlagen & Kataloge" showBack={false}>
      <PreparedTemplateBanner />
      <View style={styles.kpiGrid}>
        <PremiumKpiCard label="Systemvorlagen" value={String(stats.systemCount)} icon="🏛️" accentColor={colors.cyan} />
        <PremiumKpiCard label="Mandantenvorlagen" value={String(stats.tenantCount)} icon="🏢" accentColor={colors.success} />
        <PremiumKpiCard label="Aktiv" value={String(stats.activeCount)} icon="✅" accentColor={colors.success} />
        <PremiumKpiCard label="Archiviert" value={String(stats.archivedCount)} icon="📦" accentColor={colors.amber} />
        <PremiumKpiCard label="Module" value={String(stats.modulesWithTemplates)} icon="🧩" accentColor={colors.violet} />
      </View>

      {stats.topTemplates.length > 0 ? (
        <PremiumCard>
          <Text style={styles.sectionTitle}>Meistgenutzt</Text>
          {stats.topTemplates.map((t) => (
            <Text key={t.id} style={styles.row}>
              {t.title} · {t.usageCount}×
            </Text>
          ))}
        </PremiumCard>
      ) : null}

      <SectionPanel title="Schnellaktionen" subtitle="Vorlagenbereiche öffnen">
        <View style={styles.grid}>
          {QUICK_ACTIONS.map((action) => (
            <ModuleTile
              key={action.route}
              icon={action.icon}
              title={action.title}
              description="Öffnen"
              accentColor={colors.cyan}
              isActive
              onPress={() => router.push(action.route as never)}
            />
          ))}
        </View>
      </SectionPanel>

      <PremiumButton
        title="Einstellungen"
        variant="secondary"
        fullWidth
        onPress={() => router.push('/business/templates/settings' as never)}
      />
      <PremiumButton
        title="Kategorien"
        variant="secondary"
        fullWidth
        onPress={() => router.push('/business/templates/categories' as never)}
      />
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  kpiGrid: { flexDirection: 'row', flexWrap: 'wrap', gap: spacing.sm, marginBottom: spacing.md },
  sectionTitle: { ...typography.h3, marginBottom: spacing.sm },
  row: { ...typography.body, color: colors.textSecondary, marginBottom: spacing.xs },
  grid: { gap: spacing.sm },
});
