import { StyleSheet, Text, View } from 'react-native';
import { useRouter } from 'expo-router';
import { AppStartFooter, ScreenShell } from '@/components/layout';
import { PremiumBadge, PremiumButton, PremiumCard } from '@/components/ui';
import { APP_START_ENTRIES } from '@/data/landing/appStartEntries';
import { useDeviceClass } from '@/hooks/platform/useDeviceClass';
import { isTabletClass } from '@/lib/platform/breakpoints';
import { isDemoMode } from '@/lib/supabase/config';
import { colors, spacing, typography } from '@/theme';

export function AppStartScreen() {
  const router = useRouter();
  const deviceClass = useDeviceClass();
  const demoMode = isDemoMode();
  const columns = isTabletClass(deviceClass) ? 2 : 1;

  return (
    <ScreenShell
      title="CareSuite+"
      subtitle="Pflege & Betreuung — Premium SaaS"
      showBack={false}
      scroll
      showBreadcrumbs={false}
    >
      {demoMode ? (
        <View style={styles.demoRow}>
          <PremiumBadge label="Demo-Modus" variant="cyan" dot />
          <PremiumButton
            title="Demo-Dashboard öffnen"
            variant="secondary"
            onPress={() => router.push('/business/dashboard' as never)}
          />
        </View>
      ) : null}

      <View style={[styles.grid, { gap: spacing.md }]}>
        {APP_START_ENTRIES.map((entry) => (
          <View
            key={entry.path}
            style={[styles.cell, columns === 2 ? styles.cellHalf : styles.cellFull]}
          >
            <PremiumCard
              accentColor={entry.accentColor}
              sheen
              onPress={() => router.push(entry.path as never)}
            >
              <Text style={styles.icon}>{entry.icon}</Text>
              <Text style={styles.cardTitle}>{entry.label}</Text>
              <Text style={styles.cardDescription}>{entry.description}</Text>
            </PremiumCard>
          </View>
        ))}
      </View>

      <AppStartFooter />
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  demoRow: {
    gap: spacing.sm,
  },
  grid: {
    flexDirection: 'row',
    flexWrap: 'wrap',
  },
  cell: {
    minWidth: 0,
  },
  cellFull: {
    width: '100%',
  },
  cellHalf: {
    width: '48%',
    flexGrow: 1,
  },
  icon: {
    fontSize: 28,
    marginBottom: spacing.xs,
  },
  cardTitle: {
    ...typography.bodyStrong,
    marginBottom: spacing.xs,
  },
  cardDescription: {
    ...typography.caption,
    color: colors.textSecondary,
  },
});
