import { StyleSheet, Text } from 'react-native';
import { LockedActionBanner } from '@/components/permissions';
import { ScreenShell } from '@/components/layout';
import { TISecurityNotice } from '@/components/ti';
import { PremiumCard } from '@/components/ui';
import { usePermissions } from '@/hooks/usePermissions';
import { colors, spacing, typography } from '@/theme';

export function EGKVorbereitungScreen() {
  const { can, check, roleLabel } = usePermissions();
  if (!can('ti.egk.view')) {
    return (
      <ScreenShell title="eGK-Vorbereitung">
        <LockedActionBanner message={check('ti.egk.view').reason ?? 'Keine Berechtigung.'} roleLabel={roleLabel} />
      </ScreenShell>
    );
  }
  return (
    <ScreenShell title="eGK-Vorbereitung" subtitle="Elektronische Gesundheitskarte">
      <PremiumCard accentColor={colors.cyan}>
        <Text style={styles.title}>Vorbereitung eGK-Auslesen</Text>
        <Text style={styles.meta}>
          Kartenleser ist im Demo konfiguriert. Produktiv-Integration über TI-Connector und Edge Function ti-provider-proxy.
        </Text>
      </PremiumCard>
      <TISecurityNotice />
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  title: { ...typography.bodyStrong },
  meta: { ...typography.body, color: colors.textSecondary, marginTop: spacing.sm },
});
