import { StyleSheet, Text } from 'react-native';
import { LockedActionBanner } from '@/components/permissions';
import { ScreenShell } from '@/components/layout';
import { TISecurityNotice } from '@/components/ti';
import { PremiumCard } from '@/components/ui';
import { usePermissions } from '@/hooks/usePermissions';
import { colors, spacing, typography } from '@/theme';

export function EMPVorbereitungScreen() {
  const { can, check, roleLabel } = usePermissions();
  if (!can('ti.emp.view')) {
    return (
      <ScreenShell title="eMP-Vorbereitung">
        <LockedActionBanner message={check('ti.emp.view').reason ?? 'Keine Berechtigung.'} roleLabel={roleLabel} />
      </ScreenShell>
    );
  }
  return (
    <ScreenShell title="eMP-Vorbereitung" subtitle="Elektronischer Medikationsplan">
      <PremiumCard accentColor={colors.cyan}>
        <Text style={styles.title}>Vorbereitung eMP</Text>
        <Text style={styles.meta}>
          eMP-Integration folgt in Phase 2. Medikationspläne werden mandantenisoliert in emp_medication_plans gespeichert.
        </Text>
      </PremiumCard>
      <TISecurityNotice />
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  title: { ...typography.bodyStrong },
  meta: { ...typography.body, color: colors.textSecondary, marginTop: spacing.sm },
});
