import { FlatList, RefreshControl, StyleSheet, Text, View } from 'react-native';
import { useRouter } from 'expo-router';
import { ScreenShell } from '@/components/layout';
import {
  EmptyState,
  ErrorState,
  FilterChipGroup,
  LoadingState,
  PremiumBadge,
  PremiumButton,
  PremiumCard,
  PremiumInput,
  SuccessState,
} from '@/components/ui';
import { useInvoiceList } from '@/hooks/useInvoiceList';
import { usePermissions } from '@/hooks/usePermissions';
import { formatCurrency } from '@/lib/office';
import { WORKFLOW_STATUS_LABELS } from '@/types/workflow/status';
import { colors, spacing, typography } from '@/theme';

function formatDate(iso: string): string {
  return new Date(iso).toLocaleDateString('de-DE', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  });
}

type InvoicesListScreenProps = {
  embedded?: boolean;
};

export function InvoicesListScreen({ embedded = false }: InvoicesListScreenProps) {
  const router = useRouter();
  const { can, roleLabel } = usePermissions();
  const canView = can('office.invoices.view');
  const {
    items,
    totalCount,
    filteredCount,
    loading,
    error,
    refreshing,
    showSuccess,
    search,
    setSearch,
    statusFilter,
    setStatusFilter,
    sortKey,
    setSortKey,
    sortOptions,
    statusFilters,
    hasMore,
    loadMore,
    refresh,
    resetFilters,
    hasActiveFilters,
    isEmpty,
    isFilterEmpty,
  } = useInvoiceList();

  const header = (
    <View style={styles.toolbar}>
      {showSuccess ? (
        <SuccessState message="Rechnungsliste erfolgreich aktualisiert." />
      ) : null}

      <PremiumInput
        label="Suche"
        placeholder="Rechnungsnummer oder Klient:in…"
        value={search}
        onChangeText={setSearch}
        autoCapitalize="characters"
        autoCorrect={false}
        hint={`${filteredCount} von ${totalCount} Rechnungen`}
      />

      <Text style={styles.filterLabel}>Status</Text>
      <FilterChipGroup
        options={statusFilters}
        value={statusFilter}
        onChange={setStatusFilter}
      />

      <Text style={styles.filterLabel}>Sortierung</Text>
      <FilterChipGroup
        options={sortOptions}
        value={sortKey}
        onChange={setSortKey}
      />
    </View>
  );

  const shell = (children: React.ReactNode, title = 'Rechnungen', subtitle?: string) =>
    embedded ? (
      <View style={styles.embedded}>{children}</View>
    ) : (
      <ScreenShell title={title} subtitle={subtitle} scroll={false}>
        {children}
      </ScreenShell>
    );

  if (!canView) {
    return shell(
      <EmptyState
        title="Zugriff verweigert"
        message={`Rechnungen sind für ${roleLabel ?? 'Ihre Rolle'} nicht freigegeben.`}
      />,
    );
  }

  if (loading && items.length === 0) {
    return shell(<LoadingState message="Rechnungen werden geladen…" />, 'Rechnungen', 'Wird geladen…');
  }

  if (error && items.length === 0 && totalCount === 0) {
    return shell(<ErrorState message={error} onRetry={refresh} />, 'Rechnungen', 'Fehler');
  }

  const list = (
      <FlatList
        style={embedded ? styles.embeddedList : styles.flatList}
        data={items}
        keyExtractor={(item) => item.id}
        ListHeaderComponent={header}
        ListEmptyComponent={
          isEmpty ? (
            <EmptyState
              title="Noch keine Rechnungen"
              message="Es sind keine Rechnungen im Demo-Mandanten vorhanden."
            />
          ) : isFilterEmpty ? (
            <EmptyState
              title="Keine Treffer"
              message="Für Ihre Suche oder Filter wurden keine Rechnungen gefunden."
              actionLabel="Filter zurücksetzen"
              onAction={resetFilters}
            />
          ) : null
        }
        ListFooterComponent={
          hasMore ? (
            <PremiumButton
              title="Weitere laden"
              variant="secondary"
              fullWidth
              onPress={loadMore}
              style={styles.loadMore}
            />
          ) : filteredCount > 0 ? (
            <Text style={styles.footer}>
              {filteredCount} Rechnungen angezeigt
              {hasActiveFilters ? ' (gefiltert)' : ''}
            </Text>
          ) : null
        }
        renderItem={({ item }) => (
          <PremiumCard
            accentColor={colors.orange}
            onPress={() => router.push(`/office/invoices/${item.id}` as never)}
          >
              <View style={styles.cardHeader}>
                <Text style={styles.invoiceNumber}>{item.invoiceNumber}</Text>
                <PremiumBadge
                  label={WORKFLOW_STATUS_LABELS[item.status]}
                  variant={item.status === 'fehlerhaft' ? 'red' : 'muted'}
                />
              </View>
              <Text style={styles.clientName}>{item.clientName}</Text>
              <View style={styles.row}>
                <Text style={styles.amount}>
                  {formatCurrency(item.amountCents, item.currency)}
                </Text>
                <Text style={styles.due}>Fällig: {formatDate(item.dueDate)}</Text>
              </View>
            </PremiumCard>
        )}
        contentContainerStyle={styles.list}
        showsVerticalScrollIndicator={false}
        refreshControl={
          <RefreshControl
            refreshing={refreshing}
            onRefresh={refresh}
            tintColor={colors.primary}
          />
        }
      />
  );

  return embedded ? list : shell(list, 'Rechnungen', `${filteredCount} Einträge`);
}

const styles = StyleSheet.create({
  embedded: { flex: 1 },
  embeddedList: { flex: 1 },
  flatList: { flex: 1 },
  toolbar: { gap: spacing.sm, marginBottom: spacing.md },
  filterLabel: { ...typography.label, marginTop: spacing.xs },
  list: { paddingBottom: spacing.xxl, gap: spacing.sm },
  loadMore: { marginTop: spacing.sm, marginBottom: spacing.md },
  footer: { ...typography.caption, textAlign: 'center', marginVertical: spacing.md },
  cardHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'flex-start',
    gap: spacing.sm,
    marginBottom: spacing.xs,
  },
  invoiceNumber: { ...typography.bodyStrong, flex: 1 },
  clientName: { ...typography.caption, color: colors.textSecondary },
  row: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginTop: spacing.sm,
  },
  amount: { ...typography.h3, color: colors.orange },
  due: { ...typography.caption },
});
