import { FlatList, Pressable, StyleSheet, Text } from 'react-native';
import { useRouter } from 'expo-router';
import { ScreenShell } from '@/components/layout';
import { EmptyState, ErrorState, LoadingState, PremiumBadge, PremiumCard } from '@/components/ui';
import { useReportList } from '@/hooks/useReportList';
import { wp501A11y } from '@/lib/a11y/wp501-reporting';
import { spacing, typography } from '@/theme';

/** WP504 — Listenansicht Berichte */
export function ReportListScreen() {
  const router = useRouter();
  const { data, loading, error, refresh } = useReportList();

  if (loading && !data) {
    return (
      <ScreenShell title="Berichte" subtitle="WP 504" a11yMeta={wp501A11y}>
        <LoadingState message="Berichte werden geladen…" />
      </ScreenShell>
    );
  }

  if (error) {
    return (
      <ScreenShell title="Berichte" subtitle="Fehler" a11yMeta={wp501A11y}>
        <ErrorState title="Berichte" message={error} onRetry={refresh} />
      </ScreenShell>
    );
  }

  const items = data ?? [];

  return (
    <ScreenShell
      title="Berichte"
      subtitle="Reporting · WP 504"
      a11yMeta={wp501A11y}
      rightSlot={
        <Pressable onPress={() => router.push('/business/reporting/create' as never)}>
          <Text style={styles.link}>+ Neu</Text>
        </Pressable>
      }
    >
      <FlatList
        data={items}
        keyExtractor={(item) => item.id}
        ListEmptyComponent={<EmptyState title="Keine Berichte" message="Legen Sie einen neuen Bericht an." />}
        renderItem={({ item }) => (
          <Pressable onPress={() => router.push(`/business/reporting/${item.id}` as never)}>
            <PremiumCard style={styles.card}>
              <Text style={styles.title}>{item.title}</Text>
              <Text style={styles.meta}>{item.period}</Text>
              <PremiumBadge label={item.status} variant="cyan" />
            </PremiumCard>
          </Pressable>
        )}
      />
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  card: { marginBottom: spacing.sm },
  title: { ...typography.bodyStrong },
  meta: { ...typography.caption, marginVertical: spacing.xs },
  link: { ...typography.caption, color: '#62F3FF' },
});
