import { ScrollView, StyleSheet, Text } from 'react-native';
import { useLocalSearchParams } from 'expo-router';
import { LockedActionBanner } from '@/components/permissions';
import { ScreenShell } from '@/components/layout';
import { ErrorState, LoadingState } from '@/components/ui';
import { QmStatusBadge } from '@/components/qm';
import { useQmChapter } from '@/hooks/qm';
import { usePermissions } from '@/hooks/usePermissions';
import { colors, spacing, typography } from '@/theme';

export function QmHandbookChapterScreen() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const { can, check, roleLabel } = usePermissions();
  const { data, loading, error, refresh } = useQmChapter(id ?? '');

  if (!can('qm.view')) {
    return (
      <ScreenShell title="Kapitel" showBack>
        <LockedActionBanner message={check('qm.view').reason ?? ''} roleLabel={roleLabel} />
      </ScreenShell>
    );
  }

  if (loading && !data) {
    return (
      <ScreenShell title="Kapitel" showBack>
        <LoadingState message="Kapitel wird geladen…" />
      </ScreenShell>
    );
  }

  if (error && !data) {
    return (
      <ScreenShell title="Kapitel" showBack>
        <ErrorState title="Kapitel" message={error} onRetry={refresh} />
      </ScreenShell>
    );
  }

  return (
    <ScreenShell title={data!.title} subtitle={`Version ${data!.version}`} showBack>
      <ScrollView contentContainerStyle={styles.scroll}>
        <QmStatusBadge kind="document" status={data!.status} />
        <Text style={styles.content}>{data!.content}</Text>
      </ScrollView>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  scroll: { gap: spacing.md, paddingBottom: spacing.xxl },
  content: { ...typography.body, color: colors.textSecondary },
});
