import { useMemo, useState } from 'react';
import { StyleSheet, Text, View } from 'react-native';
import { MasterDetailLayout } from '@/components/layout';
import { PremiumBadge, SectionPanel } from '@/components/ui';
import { useOfficeMessages } from '@/hooks/useOfficeMessages';
import { usePlatformLayout } from '@/hooks/platform/usePlatformLayout';
import { WORKFLOW_STATUS_LABELS } from '@/types/workflow/status';
import { VISIBILITY_LABELS } from '@/types/portal/visibility';
import { colors, spacing, typography } from '@/theme';
import { OfficeMessagesListScreen } from './OfficeMessagesListScreen';

function OfficeMessageDetailPanel({ messageId }: { messageId: string }) {
  const { items } = useOfficeMessages();
  const message = useMemo(() => items.find((item) => item.id === messageId), [items, messageId]);

  if (!message) {
    return (
      <View style={styles.detailEmpty}>
        <Text style={styles.detailEmptyText}>Nachricht nicht gefunden.</Text>
      </View>
    );
  }

  return (
    <View style={styles.detail}>
      <SectionPanel title={message.subject} subtitle={`${message.senderName} → ${message.recipientName}`}>
        <Text style={styles.body}>{message.body}</Text>
        <View style={styles.badges}>
          <PremiumBadge
            label={WORKFLOW_STATUS_LABELS[message.status]}
            variant={message.status === 'fehlerhaft' ? 'red' : 'muted'}
          />
          <PremiumBadge label={VISIBILITY_LABELS[message.visibility]} variant="cyan" />
          {!message.readAt ? <PremiumBadge label="Ungelesen" variant="orange" /> : null}
        </View>
        <Text style={styles.meta}>
          Aktualisiert: {new Date(message.updatedAt).toLocaleString('de-DE')}
        </Text>
      </SectionPanel>
    </View>
  );
}

export function OfficeMessagesAdaptiveScreen() {
  const { useMasterDetail } = usePlatformLayout();
  const [selectedId, setSelectedId] = useState<string | null>(null);

  if (!useMasterDetail) {
    return <OfficeMessagesListScreen />;
  }

  return (
    <MasterDetailLayout
      master={<OfficeMessagesListScreen embedded onMessagePress={setSelectedId} />}
      detail={selectedId ? <OfficeMessageDetailPanel messageId={selectedId} /> : <></>}
      showDetail={!!selectedId}
    />
  );
}

const styles = StyleSheet.create({
  detail: {
    flex: 1,
    padding: spacing.md,
  },
  body: {
    ...typography.body,
    color: colors.textSecondary,
    marginBottom: spacing.md,
  },
  badges: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: spacing.xs,
    marginBottom: spacing.sm,
  },
  meta: {
    ...typography.caption,
    color: colors.textMuted,
  },
  detailEmpty: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    padding: spacing.xl,
  },
  detailEmptyText: {
    ...typography.body,
    color: colors.textMuted,
  },
});
