import { ScrollView, StyleSheet, Text, View } from 'react-native';
import { useRouter } from 'expo-router';
import { LockedActionBanner } from '@/components/permissions';
import { ScreenShell } from '@/components/layout';
import {
  EmptyState,
  ErrorState,
  LoadingState,
  PremiumBadge,
  PremiumCard,
} from '@/components/ui';
import { useCatalogList } from '@/hooks/useCatalogList';
import { usePermissions } from '@/hooks/usePermissions';
import { CATALOG_TYPE_LABELS } from '@/types/modules/catalog';
import { WORKFLOW_STATUS_LABELS } from '@/types/workflow/status';
import { colors, spacing, typography } from '@/theme';

export function CatalogsListScreen() {
  const router = useRouter();
  const { can, check, roleLabel } = usePermissions();
  const { items, loading, error, refresh, isEmpty } = useCatalogList();

  if (!can('office.catalogs.view')) {
    return (
      <ScreenShell title="Kataloge" subtitle={roleLabel ?? 'Office'}>
        <LockedActionBanner
          message={check('office.catalogs.view').reason ?? 'Keine Berechtigung.'}
          roleLabel={roleLabel}
        />
      </ScreenShell>
    );
  }

  if (loading && items.length === 0) {
    return (
      <ScreenShell title="Kataloge" subtitle="Wird geladen…">
        <LoadingState message="Kataloge werden geladen…" />
      </ScreenShell>
    );
  }

  if (error && items.length === 0) {
    return (
      <ScreenShell title="Kataloge" subtitle="Fehler">
        <ErrorState title="Fehler" message={error} onRetry={refresh} />
      </ScreenShell>
    );
  }

  return (
    <ScreenShell title="Kataloge" subtitle="Leistungen, Tarife & Qualifikationen">
      <ScrollView contentContainerStyle={styles.scroll}>
        {isEmpty ? (
          <EmptyState title="Keine Kataloge" message="Es sind keine Kataloge angelegt." />
        ) : (
          items.map((cat) => (
            <PremiumCard
              key={cat.id}
              accentColor={colors.orange}
              onPress={() => router.push(`/office/catalogs/${cat.id}` as never)}
            >
              <View style={styles.row}>
                <Text style={styles.title}>{cat.name}</Text>
                <PremiumBadge label={CATALOG_TYPE_LABELS[cat.catalogType]} variant="muted" />
              </View>
              {cat.description ? <Text style={styles.desc}>{cat.description}</Text> : null}
              <Text style={styles.meta}>
                {cat.itemCount} Positionen · {WORKFLOW_STATUS_LABELS[cat.status]}
              </Text>
            </PremiumCard>
          ))
        )}
      </ScrollView>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  scroll: { gap: spacing.md, paddingBottom: spacing.xxl },
  row: { flexDirection: 'row', justifyContent: 'space-between', gap: spacing.sm, marginBottom: spacing.xs },
  title: { ...typography.bodyStrong, flex: 1 },
  desc: { ...typography.caption, color: colors.textSecondary },
  meta: { ...typography.caption, marginTop: spacing.xs },
});
