import { useState } from 'react';
import { StyleSheet, View } from 'react-native';
import { useRouter } from 'expo-router';
import { CatalogValueSelect, TemplateDropdownSelect } from '@/components/templates';
import { LockedActionBanner } from '@/components/permissions';
import { ScreenShell } from '@/components/layout';
import { PremiumButton, PremiumInput } from '@/components/ui';
import { createThread } from '@/features/communication/communication.service';
import { useCommunicationPermissions } from '@/hooks/communication';
import { useServiceTenantId } from '@/hooks/useTenantId';
import { useAuth } from '@/lib/auth/context';
import { renderTemplateWithVariables, getSampleVariableValues } from '@/lib/templates/templateVariables';
import { spacing } from '@/theme';

export function NewConversationScreen() {
  const router = useRouter();
  const { profile } = useAuth();
  const tenantId = useServiceTenantId();
  const perms = useCommunicationPermissions();
  const [title, setTitle] = useState('');
  const [categoryKey, setCategoryKey] = useState<string | null>(null);
  const [messageTemplateId, setMessageTemplateId] = useState('');
  const [messageBody, setMessageBody] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  if (!perms.canCreateThread) {
    return (
      <ScreenShell title="Neue Nachricht">
        <LockedActionBanner message="Keine Berechtigung zum Anlegen von Threads." />
      </ScreenShell>
    );
  }

  const handleCreate = async () => {
    if (!tenantId) {
      setError('Kein Mandant.');
      return;
    }
    setLoading(true);
    setError(null);
    const threadTitle = title.trim() || renderTemplateWithVariables(messageBody, getSampleVariableValues()).slice(0, 80);
    const result = await createThread(
      tenantId,
      { threadType: 'internal', title: threadTitle, isInternalOnly: false, isPortalVisible: false },
      profile?.roleKey,
      profile?.id,
    );
    setLoading(false);
    if (!result.ok) {
      setError(result.error);
      return;
    }
    router.replace(`/business/messages/${result.data.id}` as never);
  };

  return (
    <ScreenShell title="Neue Nachricht" subtitle="Thread anlegen">
      <View style={styles.form}>
        <CatalogValueSelect
          catalogType="message_category"
          label="Nachrichtenkategorie"
          value={categoryKey ?? ''}
          onChange={(key) => {
            setCategoryKey(key);
          }}
        />
        <PremiumInput label="Titel" value={title} onChangeText={setTitle} placeholder="Betreff oder Name" />
        <TemplateDropdownSelect
          label="Nachrichtenvorlage"
          filters={{ moduleKey: 'communication', templateType: 'message', status: 'active' }}
          value={messageTemplateId}
          onChange={(id, content) => {
            setMessageTemplateId(id);
            setMessageBody(content);
          }}
        />
        {messageBody ? (
          <PremiumInput
            label="Vorschau"
            value={renderTemplateWithVariables(messageBody, getSampleVariableValues())}
            editable={false}
            multiline
          />
        ) : null}
        {error ? <PremiumInput label="Fehler" value={error} editable={false} /> : null}
        <PremiumButton
          title="Thread erstellen"
          onPress={handleCreate}
          loading={loading}
          disabled={!title.trim() && !messageTemplateId}
        />
        <PremiumButton title="Abbrechen" variant="secondary" onPress={() => router.back()} />
      </View>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  form: { gap: spacing.md },
});
