import { useState } from 'react';
import { StyleSheet, View } from 'react-native';
import { useRouter } from 'expo-router';
import { ScreenShell } from '@/components/layout';
import { PremiumButton, PremiumKpiCard, SegmentedTabs, type TabOption } from '@/components/ui';
import { useAsyncQuery } from '@/hooks/core';
import { useServiceTenantId } from '@/hooks/useTenantId';
import { fetchBillingDashboardStats, formatCurrency } from '@/lib/office';
import { useAuth } from '@/lib/auth/context';
import { colors, spacing } from '@/theme';
import { BudgetsListScreen } from './BudgetsListScreen';
import { InvoicesListScreen } from './InvoicesListScreen';

const BILLING_TABS: TabOption[] = [
  { key: 'invoices', label: 'Rechnungen' },
  { key: 'budgets', label: 'Budgets' },
];

export function OfficeBillingScreen() {
  const router = useRouter();
  const [activeTab, setActiveTab] = useState('invoices');
  const { profile } = useAuth();
  const tenantId = useServiceTenantId();

  const statsQuery = useAsyncQuery(
    () => {
      if (!tenantId) return Promise.resolve({ ok: false as const, error: 'Kein Mandant am Profil hinterlegt.' });
      return fetchBillingDashboardStats(tenantId, profile?.roleKey);
    },
    [tenantId, profile?.roleKey],
    { enabled: !!tenantId },
  );

  const stats = statsQuery.data;

  return (
    <ScreenShell title="Abrechnung" subtitle="Rechnungen & Budgets" scroll={false}>
      {stats ? (
        <View style={styles.kpis}>
          <PremiumKpiCard
            label="Offene Rechnungen"
            value={String(stats.openInvoicesCount)}
            subValue={formatCurrency(stats.openInvoicesCents)}
            accentColor={colors.orange}
          />
          <PremiumKpiCard
            label="Überfällig"
            value={String(stats.overdueCount)}
            subValue="Fälligkeit überschritten"
            accentColor={colors.danger}
          />
          <PremiumKpiCard
            label="Aktive Budgets"
            value={String(stats.activeBudgetsCount)}
            subValue={`${stats.budgetsNearLimitCount} nahe Limit`}
            accentColor={colors.cyan}
          />
        </View>
      ) : null}

      <View style={styles.catalogLink}>
        <PremiumButton
          title="Leistungskatalog"
          variant="secondary"
          size="sm"
          onPress={() => router.push('/office/catalogs' as never)}
        />
      </View>

      <View style={styles.tabs}>
        <SegmentedTabs tabs={BILLING_TABS} activeKey={activeTab} onSelect={setActiveTab} />
      </View>

      <View style={styles.content}>
        {activeTab === 'invoices' ? (
          <InvoicesListScreen embedded />
        ) : (
          <BudgetsListScreen embedded />
        )}
      </View>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  kpis: { flexDirection: 'row', flexWrap: 'wrap', gap: spacing.sm, marginBottom: spacing.md },
  catalogLink: { marginBottom: spacing.sm },
  tabs: { marginBottom: spacing.sm },
  content: { flex: 1 },
});
