import { ScrollView, StyleSheet, Text } from 'react-native';
import { LockedActionBanner } from '@/components/permissions';
import { PreparedModeBanner } from '@/components/modules/PreparedModeBanner';
import { ScreenShell } from '@/components/layout';
import { PremiumCard } from '@/components/ui';
import { usePermissions } from '@/hooks/usePermissions';
import { colors, spacing, typography } from '@/theme';

export function QmSettingsScreen() {
  const { can, check, roleLabel } = usePermissions();

  if (!can('qm.manage_settings')) {
    return (
      <ScreenShell title="QM-Einstellungen" showBack>
        <LockedActionBanner message={check('qm.manage_settings').reason ?? 'Keine Berechtigung.'} roleLabel={roleLabel} />
      </ScreenShell>
    );
  }

  return (
    <ScreenShell title="QM-Einstellungen" subtitle="Mandanten-Konfiguration" showBack>
      <ScrollView contentContainerStyle={styles.scroll}>
        <PreparedModeBanner hint="Einstellungen werden im Demo-Mandanten gespeichert — Live-Sync folgt." />
        <PremiumCard accentColor={colors.cyan}>
          <Text style={styles.title}>Review-Zyklus</Text>
          <Text style={styles.body}>Standard: 12 Monate für Verfahrensanweisungen</Text>
        </PremiumCard>
        <PremiumCard accentColor={colors.cyan}>
          <Text style={styles.title}>Freigabe-Workflow</Text>
          <Text style={styles.body}>QMB → PDL → Veröffentlichung</Text>
        </PremiumCard>
        <PremiumCard accentColor={colors.cyan}>
          <Text style={styles.title}>MD-Freigabe</Text>
          <Text style={styles.body}>Token-Gültigkeit: 90 Tage (Standard)</Text>
        </PremiumCard>
      </ScrollView>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  scroll: { gap: spacing.md, paddingBottom: spacing.xxl },
  title: { ...typography.bodyStrong, marginBottom: spacing.xs },
  body: { ...typography.body, color: colors.textSecondary },
});
