import { StyleSheet, Text, View } from 'react-native';
import { useRouter } from 'expo-router';
import { CounselingCaseListCard } from '@/components/beratung';
import { ScreenShell } from '@/components/layout';
import {
  EmptyState,
  ErrorState,
  LoadingState,
  ModuleTile,
  PremiumCard,
  SectionPanel,
  SuccessState,
} from '@/components/ui';
import { useBeratungDashboard } from '@/hooks/useBeratungDashboard';
import { usePermissions } from '@/hooks/usePermissions';
import { wp418A11y } from '@/lib/a11y/wp418-beratung';
import { colors, spacing, typography } from '@/theme';

function StatTile({ label, value, accent }: { label: string; value: number; accent: string }) {
  return (
    <PremiumCard style={styles.statTile} accentColor={accent}>
      <Text style={styles.statValue}>{value}</Text>
      <Text style={styles.statLabel}>{label}</Text>
    </PremiumCard>
  );
}

export function BeratungIndexScreen() {
  const router = useRouter();
  const { can, roleLabel } = usePermissions();
  const { stats, recentCases, loading, error, showSuccess, refresh } = useBeratungDashboard();

  if (loading && !stats) {
    return (
      <ScreenShell title="CareSuite+ Beratung" subtitle="Sozial- und Pflegeberatung">
        <LoadingState message="Dashboard wird geladen…" />
      </ScreenShell>
    );
  }

  if (error && !stats) {
    return (
      <ScreenShell title="CareSuite+ Beratung" subtitle="Fehler">
        <ErrorState message={error} onRetry={refresh} />
      </ScreenShell>
    );
  }

  return (
    <ScreenShell
      title="CareSuite+ Beratung"
      subtitle={`Sozial- und Pflegeberatung · ${roleLabel ?? 'Demo'}`}
      a11yMeta={wp418A11y}
    >
      {showSuccess ? <SuccessState message="Dashboard aktualisiert." /> : null}

      {stats ? (
        <View style={styles.statsGrid}>
          <StatTile label="Offen" value={stats.openCount} accent={colors.cyan} />
          <StatTile label="Aktiv" value={stats.activeCount} accent={colors.success} />
          <StatTile label="Termine" value={stats.upcomingAppointmentsCount} accent={colors.violet} />
          <StatTile label="Abgeschlossen" value={stats.closedThisMonthCount} accent={colors.amber} />
        </View>
      ) : null}

      <SectionPanel title="Aktuelle Fälle" subtitle="Zuletzt bearbeitet">
        {recentCases.length === 0 ? (
          <EmptyState
            title="Keine offenen Fälle"
            message="Derzeit sind keine aktiven Beratungsfälle hinterlegt."
            actionLabel="Alle Fälle anzeigen"
            onAction={() => router.push('/beratung/cases' as never)}
          />
        ) : (
          recentCases.map((counselingCase) => (
            <CounselingCaseListCard
              key={counselingCase.id}
              counselingCase={counselingCase}
              onPress={() => router.push(`/beratung/cases/${counselingCase.id}` as never)}
            />
          ))
        )}
      </SectionPanel>

      <SectionPanel title="Schnellzugriff" subtitle="Häufige Aktionen">
        <View style={styles.quickGrid}>
          <ModuleTile
            icon="📋"
            title="Alle Fälle"
            description="Suche, Filter und Status"
            accentColor={colors.cyan}
            isActive
            onPress={() => router.push('/beratung/cases' as never)}
          />
          <ModuleTile
            icon="📄"
            title="Protokolle"
            description="Fallbezogene Dokumentation"
            accentColor={colors.violet}
            isActive
            onPress={() => router.push('/beratung/protokolle' as never)}
          />
          <ModuleTile
            icon="🔔"
            title="Wiedervorlagen"
            description="Fällige Nachverfolgungen"
            accentColor={colors.amber}
            isActive
            onPress={() => router.push('/beratung/wiedervorlagen' as never)}
          />
          <ModuleTile
            icon="📈"
            title="Auswertungen"
            description="KPIs und Kennzahlen"
            accentColor={colors.success}
            preparedOnly
            onPress={() => router.push('/beratung/auswertungen' as never)}
          />
          <ModuleTile
            icon="⚙️"
            title="Einstellungen"
            description="Modul-Konfiguration"
            accentColor={colors.textMuted}
            preparedOnly
            onPress={() => router.push('/beratung/settings' as never)}
          />
        </View>
        {!can('beratung.cases.view') ? (
          <Text style={styles.readOnlyHint}>
            Lesemodus — Beratungsfälle sind für {roleLabel ?? 'Ihre Rolle'} nicht sichtbar.
          </Text>
        ) : null}
      </SectionPanel>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  statsGrid: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: spacing.sm,
    marginBottom: spacing.md,
  },
  statTile: { width: '47%', flexGrow: 1 },
  statValue: { ...typography.h2, marginBottom: 4 },
  statLabel: { ...typography.caption },
  quickGrid: { gap: spacing.md, marginBottom: spacing.md },
  readOnlyHint: { ...typography.caption, color: colors.textMuted },
});
