import { RefreshControl, ScrollView, StyleSheet, Text, View } from 'react-native';
import { useRouter } from 'expo-router';
import { ScreenShell } from '@/components/layout';
import {
  EmptyState,
  ErrorState,
  LoadingState,
  PremiumBadge,
  PremiumButton,
  PremiumCard,
} from '@/components/ui';
import { useOcrJobList } from '@/hooks/useOcrJobList';
import { WORKFLOW_STATUS_LABELS } from '@/types/workflow/status';
import { colors, spacing, typography } from '@/theme';

export function OcrJobsListScreen() {
  const router = useRouter();
  const { items, loading, error, refresh } = useOcrJobList();

  return (
    <ScreenShell
      title="OCR-Jobs"
      subtitle="Azure Document Intelligence"
      rightSlot={
        <PremiumButton title="Hub" size="sm" variant="ghost" onPress={() => router.back()} />
      }
    >
      {loading && items.length === 0 ? (
        <LoadingState message="OCR-Jobs werden geladen…" />
      ) : error && items.length === 0 ? (
        <ErrorState title="Fehler" message={error} onRetry={refresh} />
      ) : (
        <ScrollView
          refreshControl={
            <RefreshControl refreshing={loading} onRefresh={refresh} tintColor={colors.primary} />
          }
          contentContainerStyle={styles.scroll}
        >
          {items.length === 0 ? (
            <EmptyState title="Keine Jobs" message="Noch keine OCR-Verarbeitungen." />
          ) : (
            items.map((job) => (
              <PremiumCard
                key={job.id}
                accentColor={job.status === 'fehlerhaft' ? colors.danger : colors.cyan}
                onPress={() => router.push(`/business/platform/ocr/${job.id}` as never)}
              >
                <View style={styles.row}>
                  <Text style={styles.title}>{job.sourceDocumentTitle}</Text>
                  <PremiumBadge label={WORKFLOW_STATUS_LABELS[job.status]} variant="muted" />
                </View>
                {job.confidence != null ? (
                  <Text style={styles.meta}>Konfidenz: {Math.round(job.confidence * 100)}%</Text>
                ) : null}
              </PremiumCard>
            ))
          )}
        </ScrollView>
      )}
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  scroll: { gap: spacing.md, paddingBottom: spacing.xxl },
  row: { flexDirection: 'row', justifyContent: 'space-between', gap: spacing.sm, marginBottom: spacing.xs },
  title: { ...typography.bodyStrong, flex: 1 },
  meta: { ...typography.caption, color: colors.textSecondary },
});
