import { FlatList, RefreshControl, StyleSheet, Text, View } from 'react-native';
import { useRouter } from 'expo-router';
import { PreparedModeBanner } from '@/components/modules/PreparedModeBanner';
import { ScreenShell } from '@/components/layout';
import { EmptyState, ErrorState, LoadingState, PremiumBadge, PremiumCard } from '@/components/ui';
import { useAsyncQuery } from '@/hooks/core/useAsyncQuery';
import { usePermissions } from '@/hooks/usePermissions';
import { useServiceTenantId } from '@/hooks/useTenantId';
import { useAuth } from '@/lib/auth/context';
import { fetchFollowUps } from '@/lib/beratung/moduleExtensionService';
import type { FollowUp } from '@/types/modules/beratung';
import { colors, spacing, typography } from '@/theme';

function FollowUpCard({ item, onPress }: { item: FollowUp; onPress: () => void }) {
  return (
    <PremiumCard style={styles.card} accentColor={colors.warning} onPress={onPress}>
      <Text style={styles.title}>{item.caseSubject}</Text>
      <Text style={styles.meta}>
        Fällig: {new Date(item.dueAt).toLocaleDateString('de-DE')} · {item.assigneeName}
      </Text>
      {item.note ? <Text style={styles.content}>{item.note}</Text> : null}
      <PremiumBadge label={item.status} variant="orange" />
    </PremiumCard>
  );
}

export function FollowUpsScreen() {
  const router = useRouter();
  const { profile } = useAuth();
  const tenantId = useServiceTenantId();
  const { roleLabel } = usePermissions();

  const query = useAsyncQuery(
    () => {
      if (!tenantId) return Promise.resolve({ ok: false as const, error: 'Kein Mandant.' });
      return fetchFollowUps(tenantId, profile?.roleKey);
    },
    [tenantId, profile?.roleKey],
    { enabled: !!tenantId },
  );

  const items = query.data ?? [];

  if (query.loading && items.length === 0) {
    return (
      <ScreenShell title="Wiedervorlagen" subtitle="Wird geladen…">
        <LoadingState message="Wiedervorlagen werden geladen…" />
      </ScreenShell>
    );
  }

  if (query.error && items.length === 0) {
    return (
      <ScreenShell title="Wiedervorlagen" subtitle="Fehler">
        <ErrorState message={query.error} onRetry={query.refresh} />
      </ScreenShell>
    );
  }

  return (
    <ScreenShell title="Wiedervorlagen" subtitle={`Fristen · ${roleLabel ?? 'Demo'}`} scroll={false}>
      <FlatList
        data={items}
        keyExtractor={(item) => item.id}
        ListHeaderComponent={
          <View style={styles.header}>
            <PreparedModeBanner hint="Erinnerungen und Kalender-Sync folgen — Demo-Wiedervorlagen verfügbar." />
            <Text style={styles.count}>{items.length} offene Wiedervorlagen</Text>
          </View>
        }
        ListEmptyComponent={
          <EmptyState title="Keine Wiedervorlagen" message="Alle Beratungsfälle sind ohne anstehende Fristen." />
        }
        renderItem={({ item }) => (
          <FollowUpCard item={item} onPress={() => router.push(`/beratung/cases/${item.caseId}` as never)} />
        )}
        contentContainerStyle={styles.list}
        refreshControl={
          <RefreshControl refreshing={query.refreshing} onRefresh={query.refresh} tintColor={colors.primary} />
        }
      />
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  header: { marginBottom: spacing.sm },
  count: { ...typography.caption, color: colors.textMuted, marginBottom: spacing.sm },
  list: { paddingBottom: spacing.xxl },
  card: { marginBottom: spacing.sm },
  title: { ...typography.h3, marginBottom: spacing.xs },
  meta: { ...typography.caption, color: colors.textMuted, marginBottom: spacing.xs },
  content: { ...typography.body, marginBottom: spacing.sm },
});
