import { RefreshControl, ScrollView, StyleSheet } from 'react-native';
import { useRouter } from 'expo-router';
import { LockedActionBanner } from '@/components/permissions';
import { ScreenShell } from '@/components/layout';
import { ErrorState, LoadingState, EmptyState } from '@/components/ui';
import { QmChapterTree } from '@/components/qm';
import { useQmHandbook } from '@/hooks/qm';
import { usePermissions } from '@/hooks/usePermissions';
import { colors, spacing } from '@/theme';

export function QmHandbookScreen() {
  const router = useRouter();
  const { can, check, roleLabel } = usePermissions();
  const { handbook, chapters, loading, error, refresh } = useQmHandbook();

  if (!can('qm.view')) {
    return (
      <ScreenShell title="QM-Handbuch" showBack>
        <LockedActionBanner message={check('qm.view').reason ?? ''} roleLabel={roleLabel} />
      </ScreenShell>
    );
  }

  if (loading && !chapters.length) {
    return (
      <ScreenShell title="QM-Handbuch" showBack>
        <LoadingState message="Handbuch wird geladen…" />
      </ScreenShell>
    );
  }

  if (error && !chapters.length) {
    return (
      <ScreenShell title="QM-Handbuch" showBack>
        <ErrorState title="Handbuch" message={error} onRetry={refresh} />
      </ScreenShell>
    );
  }

  return (
    <ScreenShell
      title="QM-Handbuch"
      subtitle={handbook ? `${handbook.title} v${handbook.version}` : `${chapters.length} Kapitel`}
      showBack
    >
      <ScrollView
        refreshControl={<RefreshControl refreshing={loading} onRefresh={refresh} tintColor={colors.primary} />}
        contentContainerStyle={styles.scroll}
      >
        {chapters.length === 0 ? (
          <EmptyState title="Keine Kapitel" message="Handbuch ist leer." />
        ) : (
          <QmChapterTree
            chapters={chapters}
            onSelect={(ch) => router.push(`/business/office/qm/handbook/${ch.id}` as never)}
          />
        )}
      </ScrollView>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({ scroll: { gap: spacing.md, paddingBottom: spacing.xxl } });
