import { FlatList, RefreshControl, StyleSheet, Text, View } from 'react-native';
import { ScreenShell } from '@/components/layout';
import {
  EmptyState,
  ErrorState,
  FilterChipGroup,
  LoadingState,
  PremiumBadge,
  PremiumButton,
  PremiumCard,
  PremiumInput,
  SuccessState,
} from '@/components/ui';
import { useOfficeMessages } from '@/hooks/useOfficeMessages';
import { usePermissions } from '@/hooks/usePermissions';
import { VISIBILITY_LABELS } from '@/types/portal/visibility';
import { WORKFLOW_STATUS_LABELS } from '@/types/workflow/status';
import { colors, spacing, typography } from '@/theme';

function formatDate(iso: string): string {
  return new Date(iso).toLocaleDateString('de-DE', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  });
}

export function OfficeMessagesListScreen({
  onMessagePress,
  embedded = false,
}: {
  onMessagePress?: (id: string) => void;
  embedded?: boolean;
} = {}) {
  const { can, roleLabel } = usePermissions();
  const canView = can('office.messages.view');
  const {
    items,
    totalCount,
    filteredCount,
    unreadCount,
    loading,
    error,
    refreshing,
    showSuccess,
    search,
    setSearch,
    statusFilter,
    setStatusFilter,
    sortKey,
    setSortKey,
    sortOptions,
    statusFilters,
    hasMore,
    loadMore,
    refresh,
    resetFilters,
    hasActiveFilters,
    isEmpty,
    isFilterEmpty,
  } = useOfficeMessages();

  const header = (
    <View style={styles.toolbar}>
      {showSuccess ? <SuccessState message="Nachrichten erfolgreich aktualisiert." /> : null}

      {unreadCount > 0 ? (
        <Text style={styles.unread}>{unreadCount} ungelesen</Text>
      ) : null}

      <PremiumInput
        label="Suche"
        placeholder="Betreff, Absender oder Empfänger…"
        value={search}
        onChangeText={setSearch}
        autoCorrect={false}
        hint={`${filteredCount} von ${totalCount} Nachrichten`}
      />

      <Text style={styles.filterLabel}>Status</Text>
      <FilterChipGroup options={statusFilters} value={statusFilter} onChange={setStatusFilter} />

      <Text style={styles.filterLabel}>Sortierung</Text>
      <FilterChipGroup options={sortOptions} value={sortKey} onChange={setSortKey} />
    </View>
  );

  if (!canView) {
    return (
      <ScreenShell title="Nachrichten" subtitle="Kein Zugriff">
        <EmptyState
          title="Zugriff verweigert"
          message={`Office-Nachrichten sind für ${roleLabel ?? 'Ihre Rolle'} nicht freigegeben.`}
        />
      </ScreenShell>
    );
  }

  if (loading && items.length === 0) {
    return (
      <ScreenShell title="Nachrichten" subtitle="Wird geladen…">
        <LoadingState message="Office-Nachrichten werden geladen…" />
      </ScreenShell>
    );
  }

  if (error && items.length === 0 && totalCount === 0) {
    return (
      <ScreenShell title="Nachrichten" subtitle="Fehler">
        <ErrorState message={error} onRetry={refresh} />
      </ScreenShell>
    );
  }

  return (
    <ScreenShell title="Nachrichten" subtitle={`${filteredCount} Einträge`} showBack={embedded ? false : undefined} scroll={false}>
      <FlatList
        style={styles.flatList}
        data={items}
        keyExtractor={(item) => item.id}
        ListHeaderComponent={header}
        ListEmptyComponent={
          isEmpty ? (
            <EmptyState
              title="Keine Nachrichten"
              message="Es sind keine Office-Nachrichten im Demo-Mandanten vorhanden."
            />
          ) : isFilterEmpty ? (
            <EmptyState
              title="Keine Treffer"
              message="Für Ihre Suche oder Filter wurden keine Nachrichten gefunden."
              actionLabel="Filter zurücksetzen"
              onAction={resetFilters}
            />
          ) : null
        }
        ListFooterComponent={
          hasMore ? (
            <PremiumButton
              title="Weitere laden"
              variant="secondary"
              fullWidth
              onPress={loadMore}
              style={styles.loadMore}
            />
          ) : filteredCount > 0 ? (
            <Text style={styles.footer}>
              {filteredCount} Nachrichten angezeigt
              {hasActiveFilters ? ' (gefiltert)' : ''}
            </Text>
          ) : null
        }
        renderItem={({ item }) => (
          <PremiumCard
            accentColor={item.readAt ? undefined : colors.orange}
            onPress={
              onMessagePress
                ? () => onMessagePress(item.id)
                : undefined
            }
          >
            <View style={styles.cardHeader}>
              <Text style={[styles.subject, !item.readAt && styles.unreadSubject]}>
                {item.subject}
              </Text>
              {!item.readAt ? <PremiumBadge label="Neu" variant="orange" /> : null}
            </View>
            <Text style={styles.body} numberOfLines={3}>
              {item.body}
            </Text>
            <View style={styles.footerRow}>
              <Text style={styles.meta}>
                Von {item.senderName} an {item.recipientName} · {formatDate(item.updatedAt)}
              </Text>
            </View>
            <View style={styles.badges}>
              <PremiumBadge
                label={WORKFLOW_STATUS_LABELS[item.status]}
                variant={item.status === 'fehlerhaft' ? 'red' : 'muted'}
              />
              <PremiumBadge label={VISIBILITY_LABELS[item.visibility]} variant="cyan" />
            </View>
          </PremiumCard>
        )}
        contentContainerStyle={styles.list}
        showsVerticalScrollIndicator={false}
        refreshControl={
          <RefreshControl refreshing={refreshing} onRefresh={refresh} tintColor={colors.primary} />
        }
      />
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  flatList: { flex: 1 },
  toolbar: { gap: spacing.sm, marginBottom: spacing.md },
  unread: {
    ...typography.caption,
    color: colors.orange,
    fontWeight: '600',
  },
  filterLabel: { ...typography.label, marginTop: spacing.xs },
  list: { paddingBottom: spacing.xxl, gap: spacing.sm },
  loadMore: { marginTop: spacing.sm, marginBottom: spacing.md },
  footer: { ...typography.caption, textAlign: 'center', marginVertical: spacing.md },
  cardHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'flex-start',
    gap: spacing.sm,
    marginBottom: spacing.xs,
  },
  subject: { ...typography.bodyStrong, flex: 1 },
  unreadSubject: { color: colors.orange },
  body: { ...typography.body, color: colors.textSecondary },
  footerRow: { marginTop: spacing.sm },
  meta: { ...typography.caption },
  badges: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: spacing.xs,
    marginTop: spacing.sm,
  },
});
