import type { ServiceResult } from '@/types';
import { getSupabaseClient } from '@/lib/supabase/client';
import { fromUnknownTable } from '@/lib/supabase/untypedTable';
import { SERVICE_ERRORS } from '@/lib/services/errors';

function unavailable<T>(): ServiceResult<T> {
  return { ok: false, error: SERVICE_ERRORS.supabaseUnavailable };
}

function notConfigured<T>(): ServiceResult<T> {
  return { ok: false, error: 'QM-Modul: Supabase-Tabellen vorbereitet — Live-Betrieb folgt nach Migration 0014.' };
}

export const qmSupabaseRepository = {
  async listChapters(tenantId: string): Promise<ServiceResult<unknown[]>> {
    const supabase = getSupabaseClient();
    if (!supabase) return unavailable();
    const { data, error } = await fromUnknownTable(supabase, 'qm_handbook_chapters')
      .select('*')
      .eq('tenant_id', tenantId)
      .order('sort_order');
    if (error) return notConfigured();
    return { ok: true, data: data ?? [] };
  },

  async listDocuments(tenantId: string): Promise<ServiceResult<unknown[]>> {
    const supabase = getSupabaseClient();
    if (!supabase) return unavailable();
    const { data, error } = await fromUnknownTable(supabase, 'qm_documents')
      .select('*')
      .eq('tenant_id', tenantId)
      .order('document_number');
    if (error) return notConfigured();
    return { ok: true, data: data ?? [] };
  },

  async listMdPackages(tenantId: string): Promise<ServiceResult<unknown[]>> {
    const supabase = getSupabaseClient();
    if (!supabase) return unavailable();
    const { data, error } = await fromUnknownTable(supabase, 'md_audit_packages')
      .select('*')
      .eq('tenant_id', tenantId)
      .order('created_at', { ascending: false });
    if (error) return notConfigured();
    return { ok: true, data: data ?? [] };
  },
};
