import { useState } from 'react';
import { StyleSheet, Text, View } from 'react-native';
import { useRouter } from 'expo-router';
import { ScreenShell } from '@/components/layout';
import { ErrorState, PremiumButton, PremiumCard, SuccessState } from '@/components/ui';
import { ROLE_LABELS } from '@/data/demo';
import { getDemoLoginLabel } from '@/lib/auth';
import { useAuth } from '@/lib/auth/context';
import { getPostLoginRedirect } from '@/lib/navigation';
import type { RoleKey } from '@/types';
import { colors, spacing, typography } from '@/theme';

type DemoLoginScreenProps = {
  title: string;
  subtitle: string;
  roles: RoleKey[];
};

export function DemoLoginScreen({ title, subtitle, roles }: DemoLoginScreenProps) {
  const router = useRouter();
  const { signInDemo, isLoading } = useAuth();
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  const handleLogin = async (roleKey: RoleKey) => {
    setError(null);
    setSuccess(false);
    try {
      await signInDemo(roleKey);
      setSuccess(true);
      const target = getPostLoginRedirect(roleKey);
      setTimeout(() => router.replace(target), 400);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Anmeldung fehlgeschlagen.');
    }
  };

  return (
    <ScreenShell title={title} subtitle={subtitle}>
      <PremiumCard accentColor={colors.orange}>
        <Text style={styles.hint}>
          Demo-Anmeldung ohne Passwort. Wählen Sie eine Rolle — die Session wird nur lokal
          simuliert (kein Supabase).
        </Text>
      </PremiumCard>

      {error ? <ErrorState message={error} onRetry={() => setError(null)} /> : null}
      {success ? (
        <SuccessState message="Anmeldung erfolgreich — Weiterleitung…" />
      ) : null}

      <View style={styles.roles}>
        {roles.map((roleKey) => (
          <PremiumButton
            key={roleKey}
            title={getDemoLoginLabel(roleKey)}
            onPress={() => handleLogin(roleKey)}
            loading={isLoading}
            fullWidth
          />
        ))}
      </View>

      <Text style={styles.roleHint}>
        Verfügbare Rollen: {roles.map((r) => ROLE_LABELS[r]).join(' · ')}
      </Text>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  hint: { ...typography.body },
  roles: { gap: spacing.sm },
  roleHint: { ...typography.caption, textAlign: 'center' },
});
