import { StyleSheet, Text, View } from 'react-native';
import { useRouter } from 'expo-router';
import { ScreenShell } from '@/components/layout';
import { PremiumBadge, PremiumButton, PremiumCard, SectionPanel } from '@/components/ui';
import { MODULE_NAV_CONFIG } from '@/data/demo/navigation';
import { PRODUCT_LABELS } from '@/data/demo/products';
import { OFFICE_MODULE_KEY } from '@/lib/modules/constants';
import { formatPriceEur, getModulePrice } from '@/lib/billing';
import { useModuleAccess } from '@/hooks/useModuleAccess';
import type { EffectiveModuleAccess } from '@/types';
import { spacing, typography, colors } from '@/theme';

function getStatusBadges(module: EffectiveModuleAccess | undefined) {
  if (!module) return [] as { label: string; variant: 'green' | 'cyan' | 'orange' | 'muted' | 'red' }[];

  const badges: { label: string; variant: 'green' | 'cyan' | 'orange' | 'muted' | 'red' }[] = [];

  if (module.isEffective) {
    badges.push({ label: 'Freigeschaltet', variant: 'green' });
  } else {
    badges.push({ label: 'Nicht aktiv', variant: 'red' });
    return badges;
  }

  if (module.productKey === OFFICE_MODULE_KEY) {
    badges.push({ label: 'Basis-Modul', variant: 'orange' });
  }

  if (module.accessSource === 'purchased') {
    badges.push({ label: 'Gebucht', variant: 'cyan' });
  } else if (module.accessSource === 'included_base') {
    badges.push({ label: 'Inklusive', variant: 'muted' });
  } else if (module.accessSource === 'trial') {
    badges.push({ label: 'Testphase', variant: 'cyan' });
  }

  return badges;
}

export function ModuleOverviewScreen() {
  const router = useRouter();
  const { modules } = useModuleAccess();

  return (
    <ScreenShell title="Module verwalten" subtitle="Freischaltung je Mandant">
      <SectionPanel
        title="Modul-Status"
        subtitle="CareSuite+ Office ist Basisverwaltung und wird mit jedem Fachmodul automatisch enthalten"
      >
        <View style={styles.list}>
          {modules.map((module) => {
            const config = MODULE_NAV_CONFIG[module.productKey];
            const badges = getStatusBadges(module);

            return (
              <PremiumCard key={module.productKey}>
                <View style={styles.header}>
                  <Text style={styles.title}>{PRODUCT_LABELS[module.productKey]}</Text>
                  <Text style={styles.subtitle}>{config.description}</Text>
                  <Text style={styles.price}>
                    {module.accessSource === 'included_base'
                      ? 'Inklusive (Basisverwaltung)'
                      : formatPriceEur(getModulePrice(module.productKey))}
                  </Text>
                </View>
                <View style={styles.row}>
                  <PremiumBadge
                    label={PRODUCT_LABELS[module.productKey]}
                    variant={module.isEffective ? 'green' : 'muted'}
                    dot
                  />
                  {badges.map((badge) => (
                    <PremiumBadge key={badge.label} label={badge.label} variant={badge.variant} />
                  ))}
                </View>
                {module.accessSource === 'included_base' && module.includedByModuleKey ? (
                  <Text style={styles.hint}>
                    Enthalten über {PRODUCT_LABELS[module.includedByModuleKey]}
                  </Text>
                ) : null}
                {!module.isEffective ? (
                  <PremiumButton
                    title="Live-Freischaltung vorbereitet"
                    variant="secondary"
                    size="sm"
                    disabled
                  />
                ) : (
                  <PremiumButton
                    title="Modul öffnen"
                    size="sm"
                    onPress={() => router.push(config.path as never)}
                  />
                )}
              </PremiumCard>
            );
          })}
        </View>
      </SectionPanel>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  list: { gap: spacing.sm },
  header: { marginBottom: spacing.sm },
  title: { ...typography.bodyStrong, color: colors.textPrimary },
  subtitle: { ...typography.caption, color: colors.textSecondary, marginTop: 2 },
  price: { ...typography.caption, color: colors.cyan, marginTop: spacing.xs },
  row: { flexDirection: 'row', flexWrap: 'wrap', gap: spacing.sm, marginBottom: spacing.sm },
  hint: { ...typography.caption, color: colors.textSecondary, marginBottom: spacing.sm },
});
