import { useCallback, useMemo, useState } from 'react';
import { fetchSubscriptionOverview, previewCart } from '@/lib/business';
import { calculateCartTotal, type CartOptions, type CartPreview } from '@/lib/billing';
import type { ProductKey } from '@/types';
import { useAuth } from '@/lib/auth/context';
import { DEMO_TENANT_ID } from '@/data/demo/tenant';
import { isDemoMode } from '@/lib/supabase/config';
import { useServiceTenantId } from '@/hooks/useTenantId';
import { useAsyncQuery } from './core';

export function useSubscription() {
  const { profile } = useAuth();
  const roleKey = profile?.roleKey ?? null;
  const serviceTenantId = useServiceTenantId();
  const tenantId = serviceTenantId ?? (isDemoMode() ? DEMO_TENANT_ID : null);

  const [cartOptions, setCartOptions] = useState<CartOptions>({
    billingInterval: 'monthly',
    promoCode: null,
    userCount: 5,
  });
  const [previewModules, setPreviewModules] = useState<ProductKey[] | null>(null);

  const query = useAsyncQuery(
    () => fetchSubscriptionOverview(roleKey, tenantId),
    [roleKey, tenantId],
  );
  const refresh = useCallback(() => query.refresh(), [query]);

  const cartPreview: CartPreview | null = useMemo(() => {
    if (previewModules) {
      return calculateCartTotal(previewModules, cartOptions);
    }
    return query.data?.cartPreview ?? null;
  }, [previewModules, cartOptions, query.data?.cartPreview]);

  const updateCartOptions = useCallback((patch: Partial<CartOptions>) => {
    setCartOptions((prev) => ({ ...prev, ...patch }));
  }, []);

  const previewModuleCart = useCallback(
    async (modules: ProductKey[], options?: CartOptions) => {
      const merged = { ...cartOptions, ...options };
      setPreviewModules(modules);
      setCartOptions(merged);
      return previewCart(modules, merged);
    },
    [cartOptions],
  );

  const resetCartPreview = useCallback(() => {
    setPreviewModules(null);
  }, []);

  return {
    data: query.data,
    loading: query.loading,
    error: query.error,
    refresh,
    cartPreview,
    cartOptions,
    updateCartOptions,
    previewModuleCart,
    resetCartPreview,
    tenantId,
  };
}
