import { FlatList, RefreshControl, StyleSheet, Text, View } from 'react-native';
import { useRouter } from 'expo-router';
import { LockedActionBanner } from '@/components/permissions';
import { ScreenShell } from '@/components/layout';
import {
  EmptyState,
  ErrorState,
  LoadingState,
  PremiumBadge,
  PremiumCard,
  PremiumInput,
  SuccessState,
} from '@/components/ui';
import { useCareRecordList } from '@/hooks/useCareRecordList';
import { usePermissions } from '@/hooks/usePermissions';
import { WORKFLOW_STATUS_LABELS } from '@/types/workflow/status';
import { colors, spacing, typography } from '@/theme';

function formatDate(iso: string): string {
  return new Date(iso).toLocaleString('de-DE', {
    day: '2-digit',
    month: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
  });
}

export function CareRecordsListScreen() {
  const router = useRouter();
  const { can, check, roleLabel } = usePermissions();
  const {
    items,
    filteredCount,
    loading,
    error,
    refreshing,
    showSuccess,
    search,
    setSearch,
    refresh,
    isEmpty,
  } = useCareRecordList();

  if (!can('assist.records.view')) {
    return (
      <ScreenShell title="Nachweise" subtitle="Kein Zugriff" showBack={false}>
        <LockedActionBanner
          message={check('assist.records.view').reason ?? 'Keine Berechtigung.'}
          roleLabel={roleLabel}
        />
      </ScreenShell>
    );
  }

  if (loading && items.length === 0) {
    return (
      <ScreenShell title="Nachweise" subtitle="Wird geladen…" showBack={false}>
        <LoadingState message="Leistungsnachweise werden geladen…" />
      </ScreenShell>
    );
  }

  return (
    <ScreenShell title="Nachweise" subtitle={`${filteredCount} Einträge`} showBack={false} scroll={false}>
      {showSuccess ? <SuccessState message="Liste aktualisiert." /> : null}
      {error ? <ErrorState message={error} onRetry={refresh} /> : null}

      <FlatList
        data={items}
        keyExtractor={(item) => item.id}
        ListHeaderComponent={
          <PremiumInput
            label="Suche"
            placeholder="Einsatz, Klient:in, Inhalt…"
            value={search}
            onChangeText={setSearch}
            style={styles.search}
          />
        }
        ListEmptyComponent={
          <EmptyState title="Keine Nachweise" message="Noch keine Leistungsnachweise vorhanden." />
        }
        renderItem={({ item }) => (
          <PremiumCard
            accentColor={item.hasSignature ? colors.success : colors.amber}
            onPress={() => router.push(`/assist/nachweise/${item.id}` as never)}
          >
            <View style={styles.cardHeader}>
              <Text style={styles.title}>{item.assignmentTitle}</Text>
              <PremiumBadge
                label={WORKFLOW_STATUS_LABELS[item.status]}
                variant={item.hasSignature ? 'green' : 'orange'}
                dot
              />
            </View>
            <Text style={styles.meta}>{item.clientName} · {item.employeeName}</Text>
            <Text style={styles.content} numberOfLines={2}>{item.content}</Text>
            <Text style={styles.date}>{formatDate(item.recordedAt)}</Text>
            {item.pdfReady ? (
              <Text style={styles.pdf}>PDF verfügbar</Text>
            ) : null}
          </PremiumCard>
        )}
        contentContainerStyle={styles.list}
        refreshControl={
          <RefreshControl refreshing={refreshing} onRefresh={refresh} tintColor={colors.primary} />
        }
      />
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  search: { marginBottom: spacing.md },
  list: { paddingBottom: spacing.xxl, gap: spacing.sm },
  cardHeader: { flexDirection: 'row', justifyContent: 'space-between', gap: spacing.sm },
  title: { ...typography.bodyStrong, flex: 1 },
  meta: { ...typography.caption, marginTop: 4 },
  content: { ...typography.body, marginTop: spacing.xs },
  date: { ...typography.caption, color: colors.cyan, marginTop: spacing.xs },
  pdf: { ...typography.caption, color: colors.success, marginTop: 4 },
});
