import { FlatList, RefreshControl, StyleSheet, Text, View } from 'react-native';
import { ScreenShell } from '@/components/layout';
import { LockedActionBanner } from '@/components/permissions';
import {
  EmptyState,
  ErrorState,
  FilterChipGroup,
  LoadingState,
  PremiumBadge,
  PremiumButton,
  PremiumCard,
  PremiumInput,
  SuccessState,
} from '@/components/ui';
import { useAppointmentList } from '@/hooks/useAppointmentList';
import { usePermissions } from '@/hooks/usePermissions';
import { WORKFLOW_STATUS_LABELS } from '@/types/workflow/status';
import { colors, spacing, typography } from '@/theme';

function formatDateTime(iso: string): string {
  return new Date(iso).toLocaleString('de-DE', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
}

export function AppointmentsListScreen() {
  const { can, check, roleLabel } = usePermissions();
  const canView = can('office.appointments.view');
  const {
    items,
    totalCount,
    filteredCount,
    loading,
    error,
    refreshing,
    showSuccess,
    search,
    setSearch,
    statusFilter,
    setStatusFilter,
    sortKey,
    setSortKey,
    sortOptions,
    statusFilters,
    hasMore,
    loadMore,
    refresh,
    resetFilters,
    hasActiveFilters,
    isEmpty,
    isFilterEmpty,
  } = useAppointmentList();

  if (!canView) {
    return (
      <ScreenShell title="Termine" subtitle="Kein Zugriff">
        <LockedActionBanner
          message={check('office.appointments.view').reason ?? 'Keine Berechtigung.'}
          roleLabel={roleLabel}
        />
      </ScreenShell>
    );
  }

  const header = (
    <View style={styles.toolbar}>
      {showSuccess ? <SuccessState message="Terminliste erfolgreich aktualisiert." /> : null}
      <PremiumInput
        label="Suche"
        placeholder="Titel, Klient:in oder Ort…"
        value={search}
        onChangeText={setSearch}
        hint={`${filteredCount} von ${totalCount} Terminen`}
      />
      <Text style={styles.filterLabel}>Status</Text>
      <FilterChipGroup options={statusFilters} value={statusFilter} onChange={setStatusFilter} />
      <Text style={styles.filterLabel}>Sortierung</Text>
      <FilterChipGroup options={sortOptions} value={sortKey} onChange={setSortKey} />
    </View>
  );

  if (loading && items.length === 0) {
    return (
      <ScreenShell title="Termine" subtitle="Wird geladen…">
        <LoadingState message="Termine werden geladen…" />
      </ScreenShell>
    );
  }

  if (error && items.length === 0 && totalCount === 0) {
    return (
      <ScreenShell title="Termine" subtitle="Fehler">
        <ErrorState message={error} onRetry={refresh} />
      </ScreenShell>
    );
  }

  return (
    <ScreenShell title="Termine" subtitle={`${filteredCount} Einträge`} scroll={false}>
      <FlatList
        style={styles.flatList}
        data={items}
        keyExtractor={(item) => item.id}
        ListHeaderComponent={header}
        ListEmptyComponent={
          isEmpty ? (
            <EmptyState
              title="Noch keine Termine"
              message="Es sind keine Termine im Demo-Mandanten vorhanden."
            />
          ) : isFilterEmpty ? (
            <EmptyState
              title="Keine Treffer"
              message="Für Ihre Suche oder Filter wurden keine Termine gefunden."
              actionLabel="Filter zurücksetzen"
              onAction={resetFilters}
            />
          ) : null
        }
        ListFooterComponent={
          hasMore ? (
            <PremiumButton
              title="Weitere laden"
              variant="secondary"
              fullWidth
              onPress={loadMore}
              style={styles.loadMore}
            />
          ) : filteredCount > 0 ? (
            <Text style={styles.footer}>
              {filteredCount} Termine angezeigt
              {hasActiveFilters ? ' (gefiltert)' : ''}
            </Text>
          ) : null
        }
        renderItem={({ item }) => (
          <PremiumCard accentColor={colors.violet}>
            <View style={styles.cardHeader}>
              <Text style={styles.title}>{item.title}</Text>
              <PremiumBadge label={WORKFLOW_STATUS_LABELS[item.status]} variant="muted" />
            </View>
            <Text style={styles.meta}>{item.clientName}</Text>
            {item.employeeName ? (
              <Text style={styles.meta}>Mitarbeitende:r: {item.employeeName}</Text>
            ) : null}
            <Text style={styles.datetime}>{formatDateTime(item.startsAt)}</Text>
            {item.location ? <Text style={styles.location}>{item.location}</Text> : null}
          </PremiumCard>
        )}
        contentContainerStyle={styles.list}
        refreshControl={
          <RefreshControl refreshing={refreshing} onRefresh={refresh} tintColor={colors.primary} />
        }
      />
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  flatList: { flex: 1 },
  toolbar: { gap: spacing.sm, marginBottom: spacing.md },
  filterLabel: { ...typography.label, marginTop: spacing.xs },
  list: { paddingBottom: spacing.xxl, gap: spacing.sm },
  loadMore: { marginTop: spacing.sm, marginBottom: spacing.md },
  footer: { ...typography.caption, textAlign: 'center', marginVertical: spacing.md },
  cardHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'flex-start',
    gap: spacing.sm,
    marginBottom: spacing.xs,
  },
  title: { ...typography.bodyStrong, flex: 1 },
  meta: { ...typography.caption, color: colors.textSecondary },
  datetime: { ...typography.body, marginTop: spacing.sm },
  location: { ...typography.caption, marginTop: spacing.xs },
});
