export function getDemoSisAssessments(): SisAssessment[] {
  return SIS_SEEDS.map((item) => {
    const client = demoClients.find((c) => c.id === item.clientId);
    const assessor = demoEmployees.find((e) => `${e.firstName} ${e.lastName}` === item.assessorName);
    return {
      ...item,
      clientName: client ? `${client.firstName} ${client.lastName}` : item.clientName,
      assessorName: assessor ? `${assessor.firstName} ${assessor.lastName}` : item.assessorName,
    };
  });
}

export function countDueSisReviews(): number {
  const now = Date.now();
  const in14Days = now + 14 * 86_400_000;
  return SIS_SEEDS.filter((s) => s.nextReviewAt && new Date(s.nextReviewAt).getTime() <= in14Days).length;
}
