import { fetchReportDetail } from '@/lib/reporting';
import { REPORTING_DEMO_TENANT } from '@/data/demo/reportingDemo';
import { useAuth } from '@/lib/auth/context';
import { useAsyncQuery } from '@/hooks/core/useAsyncQuery';

/** WP508 — Hooks Berichtsdetail */
export function useReportDetail(reportId: string) {
  const { profile } = useAuth();
  return useAsyncQuery(
    () => fetchReportDetail(REPORTING_DEMO_TENANT, reportId, profile?.roleKey),
    [reportId, profile?.roleKey],
  );
}
