import { StyleSheet, Text } from 'react-native';
import { LockedActionBanner } from '@/components/permissions';
import { ScreenShell } from '@/components/layout';
import { TISecurityNotice } from '@/components/ti';
import { PremiumCard } from '@/components/ui';
import { usePermissions } from '@/hooks/usePermissions';
import { colors, spacing, typography } from '@/theme';

export function EPAVorbereitungScreen() {
  const { can, check, roleLabel } = usePermissions();
  if (!can('ti.epa.view')) {
    return (
      <ScreenShell title="ePA-Vorbereitung">
        <LockedActionBanner message={check('ti.epa.view').reason ?? 'Keine Berechtigung.'} roleLabel={roleLabel} />
      </ScreenShell>
    );
  }
  return (
    <ScreenShell title="ePA-Vorbereitung" subtitle="Elektronische Patientenakte">
      <PremiumCard accentColor={colors.cyan}>
        <Text style={styles.title}>Vorbereitung ePA-Zugriff</Text>
        <Text style={styles.meta}>
          Einwilligung für ePA ist im Demo ausstehend. Vor Produktivbetrieb: Consent erteilen und ePA-Gateway konfigurieren.
        </Text>
      </PremiumCard>
      <TISecurityNotice />
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  title: { ...typography.bodyStrong },
  meta: { ...typography.body, color: colors.textSecondary, marginTop: spacing.sm },
});
