import { ReactNode } from 'react';
import { usePlatformLayout } from '@/hooks/platform/usePlatformLayout';
import { DesktopShell } from './DesktopShell';
import { MobileShell } from './MobileShell';
import { TabletShell } from './TabletShell';

type ResponsiveLayoutProps = {
  area: Parameters<typeof MobileShell>[0]['area'];
  children: ReactNode;
  accentColor?: string;
  showModuleSwitcher?: boolean;
};

/**
 * Picks the correct app shell (mobile / tablet / desktop) for the current viewport.
 */
export function ResponsiveLayout({
  area,
  children,
  accentColor,
  showModuleSwitcher,
}: ResponsiveLayoutProps) {
  const { shellVariant } = usePlatformLayout();

  if (shellVariant === 'desktop') {
    return (
      <DesktopShell
        area={area}
        accentColor={accentColor}
        showModuleSwitcher={showModuleSwitcher}
      >
        {children}
      </DesktopShell>
    );
  }

  if (shellVariant === 'tablet') {
    return (
      <TabletShell
        area={area}
        accentColor={accentColor}
        showModuleSwitcher={showModuleSwitcher}
      >
        {children}
      </TabletShell>
    );
  }

  return (
    <MobileShell area={area} accentColor={accentColor} showModuleSwitcher={showModuleSwitcher}>
      {children}
    </MobileShell>
  );
}
